INSERT INTO documents VALUES (52, 'TSRI-F04-00-001', 'TSRI-DOC-0052', 'TSRI-N052', 4, 'หมวดที่ 4', '1.ประกาศแต่งตั้งผอ. สมปอง.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง แต่งตั้งผู้อำนวยการ สำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม (ลงวันที่ 24 ตุลาคม 2567)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายเลขานุการคณะกรรมการ / HR)', 'มาตรา 48 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และประกาศ กสว. เรื่อง หลักเกณฑ์และวิธีการสรรหาและแต่งตั้งผู้อำนวยการ สกสว. พ.ศ. 2563 (มติ กสว. ครั้งที่ 10/2567)', 'แต่งตั้งผู้อำนวยการ สกสว. ให้มีวาระการดำรงตำแหน่ง 4 ปี นับตั้งแต่วันที่ 1 พฤศจิกายน 2567 เป็นต้นไป เพื่อเป็นผู้บังคับบัญชาสูงสุดและบริหารกิจการของสำนักงานตามมาตรา 50', 1, '4aeba5ea76e2bbcb...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1O2rrd_v-qpJEkbXSVhmlg_q9kxFpgiUY/view?usp=drivesdk');
INSERT INTO documents VALUES (53, 'TSRI-F04-00-002', 'TSRI-DOC-0053', 'TSRI-N053', 4, 'หมวดที่ 4', '2.คำสั่งสกสว.ที่ บค. 5_2568 แต่งตั้งรองผู้อำนวยการ สกสว..pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 5/2568 (สั่ง ณ วันที่ 21 กุมภาพันธ์ 2568)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 49 ประกอบมาตรา 50(4) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 และมติ กสว. ครั้งที่ 11/2567', 'แต่งตั้งผู้บริหารระดับสูงของสำนักงานตามจำนวนที่ กสว. กำหนด เพื่อช่วยผู้อำนวยการปฏิบัติงานตามที่ได้รับมอบหมาย ตั้งแต่วันที่ 21 กุมภาพันธ์ 2568 เป็นต้นไป', 1, '492a8a7317057cce...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1Z6vi3lnTx1K5UGO5N0xz2irZ8OL9-zBd/view?usp=drivesdk');
INSERT INTO documents VALUES (54, 'TSRI-F04-00-003', 'TSRI-DOC-0054', 'TSRI-N054', 4, 'หมวดที่ 4', '3.คำสั่งสกสว.ที่ บค. 6_2568 มอบหมายรองผู้อำนวยการ.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 6/2568 เรื่อง การมอบหมายกำกับดูแลส่วนงานตามโครงสร้างใหม่ (สั่ง ณ วันที่ 21 กุมภาพันธ์ 2568)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายกลยุทธ์องค์กร / HR)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 และมติ อนก. ครั้งที่ 1/2568 เมื่อวันที่ 10 มกราคม 2568', 'แบ่งสายการกำกับดูแลส่วนงานหลักทั้ง 5 สำนัก (F1 สำนักยุทธศาสตร์ แผน ติดตามและประเมินผล, F2 สำนักกลยุทธ์งบประมาณและโครงสร้างพื้นฐานฯ, F3 สำนักกลยุทธ์พัฒนากองทุนและระบบนิเวศฯ, F4 สำนักกลยุทธ์พัฒนาความร่วมมือนานาชาติและใช้ประโยชน์งานวิจัยฯ, F5 สำนักบริหารและพัฒนาองค์กร + โครงการวิจัย Ongoing) และหน่วยภารกิจ Intelligence Units (IU)', 2, 'de9f79d701c12720...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/13C9F4t3hq3Z0gYFFiZL31w9Qv4dmc-ny/view?usp=drivesdk');
INSERT INTO documents VALUES (55, 'TSRI-F04-00-004', 'TSRI-DOC-0055', 'TSRI-N055', 4, 'หมวดที่ 4', '4.คำสั่งสกสว. ที่ บค.7_2569 เรื่อง แต่งตั้งบุคคลตามโครงสร้างตำแหน่ง.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 7/2569 เรื่อง แต่งตั้งบุคคลตามโครงสร้างตำแหน่ง พ.ศ. 2569 (สั่ง ณ วันที่ 25 มิถุนายน 2569, 9 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 และมติ อนก. ครั้งที่ 5/2569 เมื่อวันที่ 8 พฤษภาคม 2569', 'ยกเลิกคำสั่งที่ บค. 7/2568 และ บค. 8/2568 และจัดวางบุคลากรทั้งหมดเข้าสู่ตำแหน่งตามโครงสร้างใหม่ พ.ศ. 2569 ครบทั้ง 5 สำนัก (F1–F5), 6 หน่วยภารกิจ (IU1–IU6) และหน่วยตรวจสอบภายใน (IA)', 9, '3b99883c4e246551...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1A5cMgxLTFyqxiibYKoErbbT44O8QFD-O/view?usp=drivesdk');
INSERT INTO documents VALUES (56, 'TSRI-F04-00-005', 'TSRI-DOC-0056', 'TSRI-N056', 4, 'หมวดที่ 4', '5.คำสั่ง สกสว. ที่บค. 8_2569 เรื่อง  แก้ไขรายชื่อบุคคลและชื่อตำแหน่ง.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 8/2569 เรื่อง แก้ไขรายชื่อบุคคลและชื่อตำแหน่ง ในคำสั่งแต่งตั้งบุคคลตามโครงสร้างตำแหน่ง พ.ศ. 2569 (สั่ง ณ วันที่ 9 กรกฎาคม 2569)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'ปรับปรุงแก้ไขรายการตำแหน่งในฝ่ายขับเคลื่อนการใช้ประโยชน์และการสร้างผลกระทบ (F4.2) และตำแหน่งผู้อำนวยการสำนักบริหารและพัฒนาองค์กร (F5) ให้มีผลย้อนหลังตั้งแต่วันที่ 25 มิถุนายน 2569', 1, '619f2f3e20c747a5...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1dGbvx95UPaVv0V4NrHWvTJKqBoqTxXZb/view?usp=drivesdk');
INSERT INTO documents VALUES (57, 'TSRI-F04-00-006', 'TSRI-DOC-0057', 'TSRI-N057', 4, 'หมวดที่ 4', '6.คำสั่ง สกสว. ที่บค. 9_2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 9/2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 6 กรกฎาคม 2569)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้ผ่านการประเมินผลการปฏิบัติงานในตำแหน่งรักษาการครบ 6 เดือน ให้ดำรงตำแหน่งผู้อำนวยการสำนักกลยุทธ์พัฒนากองทุนและระบบนิเวศ ววน. (F3) และผู้อำนวยการหน่วยภารกิจยุทธศาสตร์ ววน. การพัฒนาวิทยาศาสตร์ เทคโนโลยี การวิจัยและนวัตกรรม (IU5) ตั้งแต่วันที่ 14 พฤษภาคม 2569', 1, '3bd4bc456a7dd976...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/13v0v-4QAz7-1F_UHVdb9XFLDXUbB9G9X/view?usp=drivesdk');
INSERT INTO documents VALUES (58, 'TSRI-F04-00-007', 'TSRI-DOC-0058', 'TSRI-N058', 4, 'หมวดที่ 4', '7.คำสั่งสกสว. ที่ บค.10_2569 แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 10/2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 16 กรกฎาคม 2569)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้อำนวยการหน่วยภารกิจยุทธศาสตร์ ววน. การพัฒนากำลังคนและสถาบัน (IU6) ตั้งแต่วันที่ 1 มิถุนายน 2569 เป็นต้นไป', 1, '30dc36ed53164c7a...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1eApXgc2u5DUVqWSAePVBW4v5RVRzaPP9/view?usp=drivesdk');
INSERT INTO documents VALUES (59, 'TSRI-F04-00-008', 'TSRI-DOC-0059', 'TSRI-N059', 4, 'หมวดที่ 4', '8.คำสั่ง บค. 13_69 แต่งตั้งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 13/2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 7 ตุลาคม 2569)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้อำนวยการสำนักกลยุทธ์งบประมาณและโครงสร้างพื้นฐาน ระบบ ววน. (F2) ต่อเนื่องตามสัญญาจ้างรายปีหลังอายุครบ 60 ปีบริบูรณ์ ตั้งแต่วันที่ 1 ตุลาคม 2569 เป็นต้นไป', 1, 'e6715b39d58c5cbb...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/17Etm9xsla_OKi1UfjGyEOWUJ3sprMh3M/view?usp=drivesdk');
INSERT INTO documents VALUES (60, 'TSRI-F04-00-009', 'TSRI-DOC-0060', 'TSRI-N060', 4, 'หมวดที่ 4', '9.คำสั่งสกสว. ที่ บค. 14_2569 แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 14/2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 21 ตุลาคม 2569)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้บริหารระดับหน่วยภารกิจ สังกัดหน่วยภารกิจฐานข้อมูลและระบบดิจิทัล (IU1) ตั้งแต่วันที่ 1 ตุลาคม 2569 เป็นต้นไป', 1, '036f73ecb56034e0...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1lNhNOUczXiw2-Xp9IoePIiyz59bmiV04/view?usp=drivesdk');
INSERT INTO documents VALUES (61, 'TSRI-F04-00-010', 'TSRI-DOC-0061', 'TSRI-N061', 4, 'หมวดที่ 4', '9.ระเบียบว่าด้วยการกำหนดตำแหน่ง ค่าจ้างฯ พ.ศ. 2569.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการกำหนดตำแหน่ง อัตราเงินเดือน ค่าจ้าง และเงินอื่นของพนักงานและลูกจ้าง สกสว. พ.ศ. 2569 (ประกาศ 25 พ.ค. 2569, 6 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B2, B1 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 47 ประกอบมาตรา 25 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 11, 12 และ 15 แห่งข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (มติ อนก. ครั้งที่ 5/2569 วันที่ 8 พ.ค. 2569; ยกเลิกระเบียบฯ พ.ศ. 2566)', 'กำหนดโครงสร้างระดับชั้นงาน (Level 1 ถึง Level 8) และระดับชั้นงานย่อย (Sub-Level 1A ถึง 8A) พร้อมบัญชีเงินเดือน พ.ศ. 2569 แยกสายวิชาการ (เจ้าหน้าที่ทั่วไป 16,000–26,300 บาท ถึงผู้ทรงคุณวุฒิพิเศษ 141,000–225,000 บาท) และสายวิชาชีพ (ระดับ 1–5)', 6, 'cb096164473fa549...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1Du2AbgamXxv9VanfS5ZOuQX46iNZ_zY9/view?usp=drivesdk');
INSERT INTO documents VALUES (62, 'TSRI-F04-00-011', 'TSRI-DOC-0062', 'TSRI-N062', 4, 'หมวดที่ 4', '10.ประกาศ สกสว. เรื่อง หลักเกณฑ์การปรับเข้าสู่ตำแหน่งฯ.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การปรับเข้าสู่ตำแหน่งและบัญชีเงินเดือน พ.ศ. 2569 (ประกาศ ณ วันที่ 24 มิถุนายน 2569)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B2, B1 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อ 5 และข้อ 6 ของระเบียบ อนก. ว่าด้วยการกำหนดตำแหน่ง อัตราเงินเดือน ค่าจ้าง และเงินอื่นฯ พ.ศ. 2569 (ยกเลิกประกาศฯ ลงวันที่ 13 พ.ย. 2566)', 'กำหนดตารางเทียบโอนจากระบบเดิม (Sub-Grade 1A–6A) ไปสู่ระบบใหม่ (Level 1–8 / Sub-Level 1A–8A) ห้ามทำให้เงินเดือน ค่าจ้าง และเงินประจำตำแหน่งลดต่ำกว่าเดิม และเปิดให้พิจารณาปรับ Sub-Level สูงขึ้นได้อีก 1 ระดับ (แต่เมื่อเทียบโอนแล้วต้องไม่เกินระดับชั้นงาน 6)', 3, 'd13cc0737bf82708...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1-pcxxq8hRghUIoZrA_TVmX7EoFrc-w2_/view?usp=drivesdk');
INSERT INTO documents VALUES (63, 'TSRI-F04-00-012', 'TSRI-DOC-0063', 'TSRI-N063', 4, 'หมวดที่ 4', '11.ประกาศ สกสว. เรื่อง ส่วนงาน ของ สกสว.2569.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง ส่วนงานของสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม พ.ศ. 2569 (ประกาศ ณ วันที่ 19 มิถุนายน 2569)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2, A1–A5 (F5 และทุกสำนัก F1–F5)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 14/1 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (แก้ไขเพิ่มเติม ฉ.2 พ.ศ. 2566) และมติ อนก. ครั้งที่ 1/2568 (ยกเลิกประกาศส่วนงาน 29 ก.ย. 2566)', 'จัดแบ่งส่วนงานทางการของ สกสว. เป็น 12 ส่วนงานหลัก: 5 สำนัก (F1–F5 สำนักละ 4 ฝ่าย/กลุ่มงาน โดย F5 มี 4 กลุ่มงาน 10 ฝ่าย), 6 หน่วยภารกิจ (IU1 ฐานข้อมูลดิจิทัล, IU2 สนับสนุนงานอำนวยการ, IU3 พัฒนาเศรษฐกิจไทย, IU4 ยกระดับสังคม/สิ่งแวดล้อม, IU5 พัฒนา ววน., IU6 พัฒนากำลังคนและสถาบัน) และ 1 หน่วยตรวจสอบภายใน (IA)', 3, '2394f01dd530744d...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1ZD7wWNPLdbvRrU66XnEmjGdEqpwZo4q7/view?usp=drivesdk');
INSERT INTO documents VALUES (64, 'TSRI-F04-00-013', 'TSRI-DOC-0064', 'TSRI-N064', 4, 'หมวดที่ 4', '12.ภาพโครงสร้าง.pdf', 'แผนผังโครงสร้างองค์กรสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม (Organization Chart พ.ศ. 2569)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B4 (F5 ฝ่ายกลยุทธ์องค์กร & IA)', 'สอดคล้องกับประกาศ สกสว. เรื่อง ส่วนงานของ สกสว. พ.ศ. 2569 (TSRI-DOC-0063) และ พ.ร.บ.สภานโยบายฯ มาตรา 46, 48, 50 และ 63', 'แสดงสายการบังคับบัญชาและการกำกับดูแล: คณะกรรมการตรวจสอบกำกับหน่วยตรวจสอบภายใน (IA) เป็นอิสระ; ผู้อำนวยการ สกสว. และผู้บริหารกำกับดูแล 5 สำนักหลัก (F1–F5) และ 6 หน่วยภารกิจเชิงลึก (IU1–IU6)', 1, '182b928de5cb87e8...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/14pXIZ8eBTnygdPhAX8U6Ow0w-P4Vj39h/view?usp=drivesdk');
INSERT INTO documents VALUES (65, 'TSRI-F04-00-014', 'TSRI-DOC-0065', 'TSRI-N065', 4, 'หมวดที่ 4', 'คำสั่งสกสว ที่ บค. 26_2568 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 26/2568 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 26 สิงหาคม 2568)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้บริหารระดับผู้อำนวยการสำนักและผู้ช่วยผู้อำนวยการสำนักใน F1 (4 ราย), F2 (1 ราย) และ F5 (3 ราย) หลังผ่านการประเมินผลการปฏิบัติงานในตำแหน่งรักษาการครบ 6 เดือน โดยมีผลตั้งแต่วันที่ 1 พฤษภาคม 2568', 2, 'c3d3f438e88ea56f...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/19va2yfWl_2ohggCVD_WJUe4AhH53QKTI/view?usp=drivesdk');
INSERT INTO documents VALUES (66, 'TSRI-F05-00-001', 'TSRI-DOC-0066', 'TSRI-N066', 5, 'หมวดที่ 5', '1. ข้อบังคับ อนก บริหารงานบุคคล.pdf', 'ข้อบังคับคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการบริหารงานบุคคล สกสว. พ.ศ. 2563 (ประกาศ 30 ก.ย. 2563, 12 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล 5.3.2)', 'มาตรา 47 ประกอบมาตรา 25(4) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 6/2563 วันที่ 7 ส.ค. 2563; ยกเลิกข้อบังคับ สกว. พ.ศ. 2548)', 'กฎหมายแม่บทระดับสำนักงานด้านการบริหารทรัพยากรบุคคล (55 ข้อ): กำหนดนิยามพนักงาน ลูกจ้าง (สัญญาไม่เกิน 1 ปี) และเจ้าหน้าที่ของรัฐ, อัตรากำลัง, การบรรจุแต่งตั้ง, การประเมินผล, การพ้นจากงาน (อายุครบ 60 ปีบริบูรณ์เมื่อสิ้นปีงบประมาณ), สวัสดิการ และการรักษาวินัย', 12, '753055d3ba5b0fd1...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/14bSrZw55PRlxT-P_CfQyrfBlHSzwQy8F/view?usp=drivesdk');
INSERT INTO documents VALUES (67, 'TSRI-F05-00-002', 'TSRI-DOC-0067', 'TSRI-N067', 5, 'หมวดที่ 5', '2. ข้อบังคับ อนก บริหารงานบุคคล (ฉบับ 2).pdf', 'ข้อบังคับคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการบริหารงานบุคคล สกสว. (ฉบับที่ 2) พ.ศ. 2566 (ประกาศ 16 พ.ค. 2566, 4 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2, B1 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 47 ประกอบมาตรา 25 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 3/2566 เมื่อวันที่ 7 เมษายน 2566)', 'แก้ไขข้อ 11 (ให้สำนักงานทบทวนบัญชีเงินเดือนรายงานต่อ อนก. ทุก 5 ปี), เพิ่มหมวด 2/1 โครงสร้างและกรอบอัตรากำลัง (ข้อ 14–14/2 ให้ อนก. กำหนดโครงสร้างส่วนงานและกรอบอัตรากำลัง) และแก้ไขข้อ 15 แบ่งกลุ่มตำแหน่งเป็น 7 ประเภท (บริหาร, เชี่ยวชาญ, จัดการ, อาวุโสวิชาการ/วิชาชีพ, วิชาการ/วิชาชีพ, สนับสนุน, เจ้าหน้าที่ทั่วไป)', 4, '7d966c789d6f5c84...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1ZM7bd-OCGoPMwYB5K_x_Oj9nXSIi1yXb/view?usp=drivesdk');
INSERT INTO documents VALUES (68, 'TSRI-F05-00-003', 'TSRI-DOC-0068', 'TSRI-N068', 5, 'หมวดที่ 5', '3. ระเบียบ อนก วินัยและการดำเนินการทางวินัย.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยวินัยและการดำเนินการทางวินัย สกสว. พ.ศ. 2564 (6 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล & ฝ่ายกฎหมาย)', 'มาตรา 47 ประกอบมาตรา 25(4) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (มติ อนก. ครั้งที่ 2/2564 วันที่ 19 ก.พ. 2564)', 'กำหนดหลักธรรมาภิบาล 7 ประการ (ข้อ 7), ข้อปฏิบัติ 11 ประการ (ข้อ 8), ข้อห้าม 10 ประการ (ข้อ 9), ความผิดวินัยอย่างร้ายแรง (ข้อ 11), โทษทางวินัย 5 สถาน (ภาคทัณฑ์ ตัดเงินเดือน ลดเงินเดือน ปลดออก ไล่ออก) และขั้นตอนการสืบสวน/สอบสวนและการอุทธรณ์', 6, 'b1471d38d16c682d...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1CaY4goR5Sgvc3Db60CXL0Ly4_yCd7TKv/view?usp=drivesdk');
INSERT INTO documents VALUES (69, 'TSRI-F05-00-004', 'TSRI-DOC-0069', 'TSRI-N069', 5, 'หมวดที่ 5', '4. ประกาศ อนก สรรหา คัดเลือก และบรรจุเป็นพนักงานและลูกจ้าง.pdf', 'ประกาศคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และวิธีการสรรหา คัดเลือก และบรรจุแต่งตั้งบุคคลเป็นพนักงานและลูกจ้าง สกสว. พ.ศ. 2564 (9 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อ 16, ข้อ 22(1)–(2) และข้อ 26 แห่งข้อบังคับ อนก. ว่าด้วยการบริหารงานบุคคล พ.ศ. 2563', 'กำหนดกระบวนการสรรหาและคัดเลือกที่เป็นธรรม โปร่งใส องค์ประกอบคณะกรรมการสรรหา/คัดเลือก การบรรจุแต่งตั้งและการทดลองปฏิบัติงาน (ไม่น้อยกว่า 90 วัน แต่ไม่เกิน 180 วัน)', 9, '74c387eb800517ec...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1cu__pzzedb7eag9lRubwR7lAg5qhMHrI/view?usp=drivesdk');
INSERT INTO documents VALUES (70, 'TSRI-F05-00-005', 'TSRI-DOC-0070', 'TSRI-N070', 5, 'หมวดที่ 5', '5. ประกาศ สกสว. ว่าด้วย การยืมตัว.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และวิธีการให้เจ้าหน้าที่ของรัฐมาปฏิบัติงานที่สำนักงาน พ.ศ. 2567 (6 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2, B1 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 53(2) แห่งข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (มติ อนก. ครั้งที่ 1/2567 วันที่ 14 ก.พ. 2567)', 'แยก ''การยืมตัว'' (แต่งตั้งให้ดำรงตำแหน่งในสำนักงานและได้รับเงินเดือน/สวัสดิการจากสำนักงาน ทำได้คราวละ 1 ปี) ออกจาก ''การช่วยปฏิบัติงาน'' (ไม่แต่งตั้งดำรงตำแหน่งและไม่รับเงินเดือนจากสำนักงาน) พร้อมกำหนดคณะกรรมการประเมินความเหมาะสม', 6, 'dc568de084f15069...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1CFSvSUKcseXePONohICArFEFEIy9Cw95/view?usp=drivesdk');
INSERT INTO documents VALUES (71, 'TSRI-F05-00-006', 'TSRI-DOC-0071', 'TSRI-N071', 5, 'หมวดที่ 5', '6.1 ประกาศ สกสว. วิธีการลาของพนักงานและลูกจ้าง.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และวิธีการลาของพนักงานและลูกจ้าง พ.ศ. 2564 (7 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อ 6, ข้อ 26(2)–(3) และข้อ 27 แห่งข้อบังคับ อนก. ว่าด้วยการบริหารงานบุคคล พ.ศ. 2563', 'กำหนดประเภทการลา หลักเกณฑ์การอนุมัติลา และจำนวนวันลาได้รับค่าจ้าง (ลาป่วย ลากิจ ลาพักผ่อนประจำปี ลาคลอดบุตร ลาอุปสมบท/ประกอบพิธีฮัจย์ ลาตรวจเลือกทหาร และลาเพื่อพัฒนา/ศึกษาฝึกอบรม)', 7, '14f52069c33a6bd9...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1YU2XZC6UYBJzLFUK9L8S6LkLZF5TodfR/view?usp=drivesdk');
INSERT INTO documents VALUES (72, 'TSRI-F05-00-007', 'TSRI-DOC-0072', 'TSRI-N072', 5, 'หมวดที่ 5', '6.2 ประกาศ สกสว. วิธีการลาของพนักงานและลูกจ้าง (ฉ.2) พ.ศ. 2569.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และวิธีการลาของพนักงานและลูกจ้าง (ฉบับที่ 2) พ.ศ. 2569 (ประกาศ ณ วันที่ 30 มีนาคม 2569)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อ 6, ข้อ 26(2)–(3) และข้อ 27 แห่งข้อบังคับ อนก. ว่าด้วยการบริหารงานบุคคล พ.ศ. 2563', 'แก้ไขข้อ 13 ขยายสิทธิลาคลอดบุตรทั้งก่อนและหลังคลอดโดยได้รับเงินเดือนค่าจ้างได้ไม่เกิน 120 วัน และมีสิทธิลาต่อเนื่องเพื่อเลี้ยงดูบุตรได้อีกไม่เกิน 15 วัน (โดยได้รับเงินเดือน) กรณีบุตรมีภาวะเจ็บป่วยเสี่ยงโรคแทรกซ้อน ผิดปกติ หรือพิการ', 1, '100bb594effa585a...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1GqCQmq1i_G403T0hHZWRc46WGRtuozjo/view?usp=drivesdk');
INSERT INTO documents VALUES (73, 'TSRI-F05-00-008', 'TSRI-DOC-0073', 'TSRI-N073', 5, 'หมวดที่ 5', '7. ประกาศ สกสว. วัน เวลา ชั่วโมงทำงาน.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง การกำหนด วัน เวลา ชั่วโมงทำงาน วันหยุดงาน และวันหยุดประจำปีของพนักงานและลูกจ้าง พ.ศ. 2564 (2 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อบังคับ อนก. ว่าด้วยการบริหารงานบุคคล พ.ศ. 2563', 'กำหนดวันทำงานจันทร์–ศุกร์ สัปดาห์ละ 5 วัน วันละ 7 ชั่วโมงทำงาน โดยใช้ระบบเวลาทำงานเหลื่อมเวลา (Flexible Hours): เข้างานตั้งแต่ 07.00–09.30 น. และเลิกงานตั้งแต่ 15.00–17.30 น. (เวลาพักกลางวัน 12.00–13.00 น.)', 2, '415f9ba610fe55fb...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1xy6_02iJ6nh7L6gmLTYib1CWSMPmpF46/view?usp=drivesdk');
INSERT INTO documents VALUES (74, 'TSRI-F05-00-009', 'TSRI-DOC-0074', 'TSRI-N074', 5, 'หมวดที่ 5', '8. ประกาศ สกสว.นโยบายและแนวทางการปฏิบัติงานรูปแบบ WFH WFA.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายและแนวทางการปฏิบัติงานรูปแบบ Work From Home (WFH) และ Work From Anywhere (WFA) (ประกาศ 21 ก.พ. 2568, ใช้บังคับ 1 มี.ค. 2568)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (ยกเลิกประกาศ WFH/WFA ลงวันที่ 1 ก.ย. 2567)', 'กำหนดสัดส่วนการเข้าปฏิบัติงานที่สำนักงาน ร้อยละ 80 ของวันทำการในแต่ละสัปดาห์ และอนุญาตให้ปฏิบัติงานรูปแบบ WFH หรือ WFA (ภายในประเทศ) ได้ไม่เกินร้อยละ 20 ของวันทำการต่อสัปดาห์ โดยต้องลงเวลาออนไลน์ (Check-in / Check-out) และห้ามขอต่อเนื่องจากการลาพักผ่อนเพื่อวัตถุประสงค์ในการลา', 3, '0b07c89c246ce155...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/19HAM20iocAKA1wo8oGzl3Di5zaM6vjtx/view?usp=drivesdk');
INSERT INTO documents VALUES (75, 'TSRI-F05-00-010', 'TSRI-DOC-0075', 'TSRI-N075', 5, 'หมวดที่ 5', '9. ระเบียบ อนก สวัสดิการพนักงานและลูกจ้าง.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยสวัสดิการของพนักงานและลูกจ้าง สกสว. พ.ศ. 2563 (มติ อนก. ครั้งที่ 7/2563 วันที่ 4 ก.ย. 2563, 14 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2, B3 (F5 ฝ่ายทรัพยากรบุคคล & การเงิน)', 'มาตรา 47 ประกอบมาตรา 25(4)(ช) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 35 แห่งข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (ยกเลิกระเบียบ สกว. พ.ศ. 2551)', 'กำหนดสิทธิสวัสดิการค่ารักษาพยาบาล การตรวจสุขภาพประจำปี การประกันสุขภาพและอุบัติเหตุ เงินช่วยเหลือบุตร เงินช่วยเหลือการศึกษาบุตร เงินช่วยเหลือกรณีถึงแก่กรรม เงินตอบแทนความชอบในการทำงาน และกองทุนสำรองเลี้ยงชีพ', 14, 'f9ac6feb86d223a0...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1uCywpjJSbBMKQo_AyhxkonX6yHoeVjDj/view?usp=drivesdk');
INSERT INTO documents VALUES (76, 'TSRI-F05-00-011', 'TSRI-DOC-0076', 'TSRI-N076', 5, 'หมวดที่ 5', '10. ประกาศ อนก. กองทุนสำรองเลี้ยงชีพ สกสว..pdf', 'ประกาศคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยหลักเกณฑ์ วิธีการ และเงื่อนไขกองทุนสำรองเลี้ยงชีพ สกสว. พ.ศ. 2564 (3 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2, B3 (F5 ฝ่ายทรัพยากรบุคคล & การเงิน)', 'ข้อ 35 แห่งข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 และข้อ 36 แห่งระเบียบ อนก. ว่าด้วยสวัสดิการฯ พ.ศ. 2563 (มติ อนก. ครั้งที่ 1/2564 วันที่ 8 ม.ค. 2564)', 'ข้อ 5 กำหนดอัตราเงินสะสมและเงินสมทบ: สะสม 2–8% สำนักงานสมทบ 8% ของค่าจ้าง; สะสม 9–15% สำนักงานสมทบเท่ากับอัตราที่สะสมแต่ไม่เกิน 15%; ข้อ 7 อัตราการได้รับเงินสมทบตามอายุงาน (<1 ปี 0%, 1–<3 ปี 50%, 3–<5 ปี 75%, >=5 ปี 100%); แจ้งเปลี่ยนอัตราได้ปีละ 1 ครั้งในเดือนธันวาคม', 3, '1a0507a2b791ddbb...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1RAbZ6XrtW9IBBeRro6vaEp-EexgDuDjD/view?usp=drivesdk');
INSERT INTO documents VALUES (77, 'TSRI-F05-00-012', 'TSRI-DOC-0077', 'TSRI-N077', 5, 'หมวดที่ 5', '11. ระเบียบ อนก เครื่องแบบพิธีการ.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยเครื่องแบบพิธีการของผู้อำนวยการและพนักงาน สกสว. พ.ศ. 2566 (ประกาศ 10 มี.ค. 2566, 6 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 47 ประกอบมาตรา 25(4) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 2/2566 เมื่อวันที่ 3 มีนาคม 2566)', 'กำหนดเครื่องแบบพิธีการ 3 ประเภท: (1) เครื่องแบบปกติขาว, (2) เครื่องแบบเต็มยศ, (3) เครื่องแบบครึ่งยศ พร้อมแบบตราสัญลักษณ์ประดับคอเสื้อและอินทรธนูลายไทย โดยให้กรรมการใน กสว. และคณะกรรมการประเมินผลฯ มีสิทธิแต่งโดยอนุโลม (ข้อ 10)', 6, 'ff400d89b265ea55...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1hgW4sEv2qHRd94qlRspRUF6S4jX65alA/view?usp=drivesdk');
INSERT INTO documents VALUES (78, 'TSRI-F05-00-013', 'TSRI-DOC-0078', 'TSRI-N078', 5, 'หมวดที่ 5', '12. ประกาศ สกสว. นโยบายปฏิบัติงานจากเหตุการณ์แผ่นดินไหว (ฉ.2).pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายและแนวทางการปฏิบัติงานจากเหตุการณ์แผ่นดินไหว (ฉบับที่ 2) (ประกาศ ณ วันที่ 3 เมษายน 2568)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล & อาคารสถานที่)', 'อาศัยอำนาจตามมาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (ยกเลิกประกาศฉบับวันที่ 29 มีนาคม 2568)', 'กำหนดแนวทางบริหารความต่อเนื่องทางธุรกิจ (BCP) หลังตรวจสอบความมั่นคงแข็งแรงทางวิศวกรรมอาคารที่ตั้งสำนักงาน (ชั้น 14 และชั้น 15) โดยเปิดให้ผสมผสานการเข้าปฏิบัติงาน ณ สำนักงานและรูปแบบ WFH/WFA ในช่วงซ่อมแซมงานสถาปัตยกรรม', 2, '526d8fca2b756144...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1iSBDgVNEgFuRy9ZbajrJEl_rPz63N8EQ/view?usp=drivesdk');
INSERT INTO documents VALUES (79, 'TSRI-F06-00-001', 'TSRI-DOC-0079', 'TSRI-N079', 6, 'หมวดที่ 6', '1. ข้อบังคับ อนก การบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน.pdf', 'ข้อบังคับคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน สกสว. พ.ศ. 2563 (6 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B3, B4', 'B3, B4 (F5 กลุ่มบัญชีและการเงิน 5.4.1–5.4.2)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 7/2563 เมื่อวันที่ 4 กันยายน 2563)', 'กฎหมายแม่บทด้านการเงิน การบัญชี และทรัพย์สินของสำนักงาน (แยกจากเงินกองทุน ววน. ตาม ม.45): กำหนดองค์ประกอบเงินและทรัพย์สินของสำนักงาน 5 ประเภท (ข้อ 6), ให้นำเงินฝากธนาคารในวันนั้นหรืออย่างช้าในวันทำการถัดไป (ข้อ 9), การนำเงินไปหาผลประโยชน์ (ข้อ 10), ประเภทรายจ่ายและการจัดทำงบการเงินส่งผู้สอบบัญชี', 6, '0bbc89c129c5cd35...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1NwyubnA2BnDWk_NQeT-MGRX_11Ehi9w3/view?usp=drivesdk');
INSERT INTO documents VALUES (80, 'TSRI-F06-00-002', 'TSRI-DOC-0080', 'TSRI-N080', 6, 'หมวดที่ 6', '2. ระเบียบ อนก การรับเงิน การจ่ายเงิน และการเก็บรักษาเงิน.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการรับเงิน การจ่ายเงิน และการเก็บรักษาเงิน สกสว. พ.ศ. 2563 (7 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B3, B4', 'B3, B4 (F5 ฝ่ายการเงิน & ฝ่ายบัญชี)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อ 14 แห่งข้อบังคับ อนก. การบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน พ.ศ. 2563 (มติ อนก. ครั้งที่ 7/2563 วันที่ 4 ก.ย. 2563)', 'กำหนดวิธีปฏิบัติในการออกใบเสร็จรับเงิน (ห้ามขูดลบแก้ไขจำนวนเงินหรือชื่อผู้ชำระเงิน ข้อ 7), การนำส่งเงินเข้าบัญชีธนาคารในชื่อ ''สำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม'' ภายในวันที่รับหรือวันทำการถัดไป (ข้อ 10–11), อำนาจอนุมัติจ่ายเงิน การยืมเงินทดรอง และการเก็บรักษาเงิน', 7, '07328149ab2114af...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1hGjPK7TqhIqEw1h3E_5bF8lynQgDHSZq/view?usp=drivesdk');
INSERT INTO documents VALUES (81, 'TSRI-F06-00-003', 'TSRI-DOC-0081', 'TSRI-N081', 6, 'หมวดที่ 6', '3. ประกาศ สกสว. อัตราค่าธรรมเนียมการจอดรถ.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และอัตราค่าธรรมเนียมการจอดรถ พ.ศ. 2566 (ประกาศ ณ วันที่ 20 ธันวาคม 2566)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B3', 'B3 (F5 ฝ่ายอาคารสถานที่ & ฝ่ายการเงิน)', 'อาศัยอำนาจตามข้อ 5(1) แห่งระเบียบ อนก. ว่าด้วยการรับเงิน การจ่ายเงิน และการเก็บรักษาเงิน สกสว. พ.ศ. 2563', 'จัดเก็บค่าธรรมเนียมการจอดรถภายในอาคารแบบเหมาจ่ายอัตราเดือนละ 500 บาท (ตั้งแต่เดือนมกราคม 2567) โดยหักจากบัญชีเงินเดือนทุกเดือนเพื่อนำส่งนิติบุคคลอาคาร และทบทวนอัตราอย่างน้อยปีละ 1 ครั้ง', 2, '3f71810a88a7b058...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1YaqyfwGMHKp5b75O94gs2qUs4cd9n3dB/view?usp=drivesdk');
INSERT INTO documents VALUES (82, 'TSRI-F06-00-004', 'TSRI-DOC-0082', 'TSRI-N082', 6, 'หมวดที่ 6', '4. ระเบียบการเดินทางไปปฏิบัติงาน (สำเนาซ้ำกับ 005).pdf', '[สงวนรหัส / ถอนสำเนาซ้ำ] ระเบียบ อนก.สกสว. ว่าด้วยการเดินทางไปปฏิบัติงานของพนักงาน พ.ศ. 2563', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B3', 'สำนัก F5 (ฝ่ายการเงิน)', 'พ.ร.บ.สภานโยบายฯ มาตรา 45 และมาตรา 47 ประกอบมาตรา 25(4)', 'ตรวจสอบค่า SHA-256 ตรงกันทุกไบต์กับ TSRI-F06-00-005 (DOC-0083) จึงถอนรหัสซ้ำออกจากคลังใช้งานจริง คงเหลือ 100 ไฟล์ใช้งานจริง', 11, 'ตรงกับ DOC-0083', 'ซ้ำถอนออก (SHA-256 ตรงกับ 005)', 0, 'https://drive.google.com/drive/folders/1lGYjlvzdd-9CyjlBt2rdOdWdX-eLCLq9');
INSERT INTO documents VALUES (83, 'TSRI-F06-00-005', 'TSRI-DOC-0083', 'TSRI-N083', 6, 'หมวดที่ 6', '4. ระเบียบ อนก ค่าใช้จ่ายในการเดินทางไปปฏิบัติงาน.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยค่าใช้จ่ายในการเดินทางไปปฏิบัติงาน สกสว. พ.ศ. 2563 (มติ อนก. ครั้งที่ 7/2563 วันที่ 4 ก.ย. 2563, 10 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B3', 'B3 (F5 ฝ่ายการเงิน — เชื่อมคู่มือการเงิน DOC-0098)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อ 11 แห่งข้อบังคับ อนก. การบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน พ.ศ. 2563', 'กำหนดสิทธิและอัตราการเบิกค่าเบี้ยเลี้ยงเดินทาง ค่าเช่าที่พัก ค่ายานพาหนะ (รวมเงินชดเชยพาหนะส่วนตัว) และค่าใช้จ่ายอื่นในการเดินทางไปปฏิบัติงานทั้งในราชอาณาจักรและต่างประเทศ (จำแนกประเทศประเภท ก, ข และ ค) สำหรับผู้ปฏิบัติงาน ผู้บริหาร และที่ปรึกษา/ผู้เชี่ยวชาญ', 10, 'b2a21caf21d5afce...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/171ke2LFrLNo1fiFtT6CN6iaMoRKX0s9J/view?usp=drivesdk');
INSERT INTO documents VALUES (84, 'TSRI-F06-00-006', 'TSRI-DOC-0084', 'TSRI-N084', 6, 'หมวดที่ 6', '5. ระเบียบ อนก กำหนดค่าตอบแทน ค่าใช้จ่าย เบี้ยประชุม.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยหลักเกณฑ์การกำหนดค่าตอบแทน ค่าใช้จ่าย เบี้ยประชุมและประโยชน์ตอบแทนอื่นของ สกสว. พ.ศ. 2564 (3 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2, B3', 'B2, B3 (F5 ฝ่ายการเงิน & เลขานุการคณะกรรมการ)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 11/2564 เมื่อวันที่ 5 พฤศจิกายน 2564)', 'กำหนดเพดานอัตราเบิกจ่ายที่สำคัญ: (1) บุคคลภายนอกร่วมประชุม เต็มวัน <=6,000 บาท/ครึ่งวัน <=3,000 บาท (ประธาน <=8,000 บาท/วัน), (2) กลั่นกรองรายชิ้นงาน <=2,000 บาท (รวม <=20,000 บาท/รอบ) รายหน่วยงาน <=3,000 บาท (รวม <=30,000 บาท/รอบ), (3) วิทยากร <=3,000 บาท/ชม., (4) เบี้ยประชุมผู้ทรงคุณวุฒิ ประธาน 3,125 บาท/ครั้ง กรรมการ/ที่ปรึกษา 2,500 บาท/ครั้ง, (5) เหมาจ่ายเดินทางในจังหวัด <=600 บาท ข้ามจังหวัด <=800 บาท, (6) จัดเลี้ยงในสำนักงาน/รัฐ <=600 บาท/คน/วัน เอกชน <=1,800 บาท/คน/วัน (<=500 บาท/มื้อ), (7) ของที่ระลึก/พวงมาลา <=3,000 บาท', 3, '83c1e30c67fd87c2...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/18mQfYVot5OMhAuC9BKpg_qBVfTUBJLLj/view?usp=drivesdk');
INSERT INTO documents VALUES (85, 'TSRI-F06-00-007', 'TSRI-DOC-0085', 'TSRI-N085', 6, 'หมวดที่ 6', '6. ระเบียบ อนก การเบิกค่าใช้จ่าย ค่าบริการสื่อสารและโทรคมนาคม.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการเบิกค่าใช้จ่ายที่เกี่ยวข้องกับค่าบริการสื่อสารและโทรคมนาคมจากการปฏิบัติงานภายนอก สกสว. พ.ศ. 2564 (3 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B3', 'B3 (F5 ฝ่ายการเงิน)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อ 11 แห่งข้อบังคับ อนก. การเงินฯ พ.ศ. 2563 (มติ อนก. ครั้งที่ 1/2564 วันที่ 8 ม.ค. 2564; ยกเลิกระเบียบปี 2563)', 'ผู้ปฏิบัติงานที่ได้รับมอบหมายให้ปฏิบัติงานภายนอกสำนักงานรวมกันไม่น้อยกว่า 10 วันทำการในเดือนนั้น (ถือเป็นเต็มเดือน) เบิกค่าบริการสื่อสารและโทรคมนาคมได้เท่าที่จ่ายจริงแต่ไม่เกิน 500 บาท/เดือน โดยต้องยื่นเบิกภายใน 30 วันนับแต่วันที่ชำระเงิน (ไม่ใช้กับผู้ดำรงตำแหน่งบริหารที่ได้รับสนับสนุนอุปกรณ์/ค่าบริการแล้ว)', 3, 'd39e4d4bf6cf3558...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/132jZzewkfIW3t-X9TrRvWtgd2yAVoltX/view?usp=drivesdk');
INSERT INTO documents VALUES (86, 'TSRI-F06-00-008', 'TSRI-DOC-0086', 'TSRI-N086', 6, 'หมวดที่ 6', 'คำสั่ง สกสว ค่าใช้จ่ายเดินทางมาปฏิบัติงานของผู้บริหารที่ยืมตัวฯ.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง ค่าใช้จ่ายในการเดินทางมาปฏิบัติงานของผู้ดำรงตำแหน่งบริหารที่ยืมตัวมาปฏิบัติงานแบบไม่เต็มเวลาและไม่ได้มีภูมิลำเนาต้นสังกัดเดียวกับที่ตั้งสำนักงาน (สั่ง ณ วันที่ 3 มกราคม 2566)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B2, B3', 'B2, B3 (F5 ฝ่ายการเงิน & ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 5 แห่งข้อบังคับ อนก. ว่าด้วยการบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน พ.ศ. 2563', 'เบิกค่าเดินทางมาปฏิบัติงานที่สำนักงาน (ไป-กลับ) ได้ไม่เกิน 5 ครั้ง/เดือน; กรณีใช้รถยนต์ส่วนบุคคลเบิกเหมาจ่ายอัตรา 4 บาท/กิโลเมตร (ไม่เกินตั๋วเครื่องบินชั้นประหยัด); ค่าเช่าที่พักเบิกได้ไม่เกิน 2,600 บาท/วัน/คน และรวมไม่เกิน 13,000 บาท/เดือน', 1, 'd1fd464f66c661d1...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1fQD61WR9-q_QbHBjtlZJ_IcGa25yMoI4/view?usp=drivesdk');
INSERT INTO documents VALUES (87, 'TSRI-F07-00-001', 'TSRI-DOC-0087', 'TSRI-N087', 7, 'หมวดที่ 7', '1. ระเบียบ อนก ว่าด้วยประมวลจริยธรรม.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยประมวลจริยธรรมของคณะกรรมการ ผู้อำนวยการ และผู้ปฏิบัติงานของ สกสว. พ.ศ. 2564 (4 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายกลยุทธ์องค์กร / นิติการ / HR)', 'มาตรา 47 ประกอบมาตรา 25(4)(ง) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และ พ.ร.บ.มาตรฐานทางจริยธรรม พ.ศ. 2562 (มติ อนก. ครั้งที่ 4/2564 วันที่ 2 เมษายน 2564)', 'กำหนดมาตรฐานจริยธรรมอันเป็นค่านิยมหลัก 10 ประการ (ข้อ 5) และหน้าที่ปฏิบัติตน 7 ประการ (ข้อ 6); กลไกสอบสวนทางจริยธรรมตั้งคณะกรรมการสอบสวนไม่น้อยกว่า 3 คน (ข้อ 9) กรณีผู้ปฏิบัติงานฝ่าฝืนให้ ผอ.สกสว. สั่งลงโทษ กรณีกรรมการหรือ ผอ.สกสว. ฝ่าฝืนให้คณะอนุกรรมการธรรมาภิบาลเสนอ อนก.สกสว. (มติสั่งพักหน้าที่ชั่วคราวใช้เสียงไม่น้อยกว่า 3 ใน 4)', 4, 'e6c582b5bbf13365...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1hnwFp9XBr2es_Ri4EVytcNsWiT_2UGH5/view?usp=drivesdk');
INSERT INTO documents VALUES (88, 'TSRI-F07-00-002', 'TSRI-DOC-0088', 'TSRI-N088', 7, 'หมวดที่ 7', '2. ประกาศ สกสว. ข้อพึงปฏิบัติและไม่พึงปฏิบัติของบุคลากร.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง ข้อพึงปฏิบัติและไม่พึงปฏิบัติของบุคลากร สกสว. (ประกาศ ณ วันที่ 3 ธันวาคม 2567, 8 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล & ฝ่ายกลยุทธ์องค์กร)', 'มาตรา 50(2) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (ยกเลิกประกาศฉบับวันที่ 18 มกราคม 2566)', 'แปลงประมวลจริยธรรมและนโยบาย No Gift Policy สู่ตารางข้อพึงปฏิบัติ (Do) และข้อไม่พึงปฏิบัติ (Don''t) รายหมวด (ยึดมั่นสถาบันหลัก ซื่อสัตย์สุจริต/ไม่ขัดกันแห่งผลประโยชน์ กล้าตัดสินใจในสิ่งที่ถูกต้อง คุ้มครองข้อมูลส่วนบุคคล และรักษาสิ่งแวดล้อม)', 8, '30378cad9254d191...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1ijG6FyUiLpJ829aPtr9MWqGR_79jmIcG/view?usp=drivesdk');
INSERT INTO documents VALUES (89, 'TSRI-F07-00-003', 'TSRI-DOC-0089', 'TSRI-N089', 7, 'หมวดที่ 7', '3.1 ประกาศนโยบายไม่รับของขวัญ 2569_TH.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายการไม่รับของขวัญและของกำนัลทุกชนิดจากการปฏิบัติหน้าที่ (No Gift Policy) ประจำปีงบประมาณ พ.ศ. 2569 (ประกาศ 27 พ.ย. 2568)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1', 'B1 (F5 ฝ่ายกลยุทธ์องค์กร)', 'หลักธรรมาภิบาลตามรัฐธรรมนูญ มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และเกณฑ์การประเมินคุณธรรมและความโปร่งใสในการดำเนินงานของหน่วยงานภาครัฐ (ITA)', 'ประกาศเจตนารมณ์ให้ผู้บริหาร เจ้าหน้าที่ และบุคลากร สกสว. ทุกคนไม่รับของขวัญและของกำนัลทุกชนิดหรือผลประโยชน์อื่นใดจากการปฏิบัติหน้าที่ ทั้งในขณะ ก่อน และหลังการปฏิบัติหน้าที่ เพื่อป้องกันผลประโยชน์ทับซ้อน', 1, '51f53fad6d002670...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1Ak8OVJQaFkNSfJoSCPCzIK80HuzkKwvi/view?usp=drivesdk');
INSERT INTO documents VALUES (90, 'TSRI-F07-00-004', 'TSRI-DOC-0090', 'TSRI-N090', 7, 'หมวดที่ 7', '3.2 ประกาศนโยบายไม่รับของขวัญ 2569_EN.pdf', 'Official Announcement: Thailand Science Research and Innovation (TSRI) Declaration of the ''No Gift Policy'' Fiscal Year 2026 (Issued 27 November 2025)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1', 'B1, A4 (F5 ฝ่ายกลยุทธ์องค์กร & F4 ความร่วมมือนานาชาติ)', 'คู่ฉบับภาษาอังกฤษของประกาศ No Gift Policy ประจำปีงบประมาณ พ.ศ. 2569 สำหรับสื่อสารต่อองค์กรพันธมิตรต่างประเทศและเกณฑ์ประเมิน ITA สากล', 'กำหนดให้ผู้บริหารและบุคลากรทุกระดับงดรับของขวัญ ของกำนัล หรือผลประโยชน์ใดๆ ทั้งก่อน ระหว่าง และหลังการปฏิบัติหน้าที่ เพื่อธำรงความเป็นกลางและความโปร่งใสระดับสากล', 1, '7e7b9af9b091611a...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1mpuy8QSzmsIrWVBCiEH__0_THYIAtTQ3/view?usp=drivesdk');
INSERT INTO documents VALUES (91, 'TSRI-F07-00-005', 'TSRI-DOC-0091', 'TSRI-N091', 7, 'หมวดที่ 7', '4. ประกาศสกสว. แจ้งช่องทางรับเรื่องร้องเรียน.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง ประชาสัมพันธ์การรับความเห็น ข้อร้องเรียน ตลอดจนข้อเสนอแนะต่อการตรวจสอบการดำเนินงานในองค์กร (ประกาศ ณ วันที่ 4 กรกฎาคม 2568)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1', 'B1, B4 (F5 ฝ่ายกฎหมาย & หน่วยตรวจสอบภายใน IA)', 'หลักการบริหารกิจการบ้านเมืองที่ดี และมาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562', 'เปิดช่องทางรับเรื่องร้องเรียนและข้อเสนอแนะ 6 ช่องทาง: (1) ยื่นด้วยตนเอง ณ สกสว., (2) ไปรษณีย์ถึง ผอ.สกสว. ชั้น 14 อาคาร SM Tower, (3) E-mail: complaint@tsri.or.th / appeal.tsri@gmail.com, (4) โทรศัพท์ 02-278-8200 ต่อ 8373, 8387, (5) เว็บไซต์ tsri.or.th/complaint และ (6) หน่วยตรวจสอบภายใน (IA) พร้อมมาตรการคุ้มครองข้อมูลส่วนบุคคลของผู้ร้องเรียน', 1, 'd0f6b78d5a042a84...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1K1HMHyKU2XBP9a9Qi4h-ZFyzcHUt0L8d/view?usp=drivesdk');
INSERT INTO documents VALUES (92, 'TSRI-F07-00-006', 'TSRI-DOC-0092', 'TSRI-N092', 7, 'หมวดที่ 7', '5. ประกาศ สกสว. นโยบายการกำกับองค์การที่ดี 2568.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายการกำกับดูแลองค์การที่ดี (Organizational Governance) สกสว. พ.ศ. 2568 (2 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B4', 'B1, B4 (F5 ฝ่ายกลยุทธ์องค์กร & หน่วยตรวจสอบภายใน IA)', 'รัฐธรรมนูญ พ.ศ. 2560, พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546 และเกณฑ์คุณภาพการบริหารจัดการภาครัฐ (PMQA)', 'วางกรอบนโยบายและแนวปฏิบัติ Organizational Governance 4 ด้านหลัก: (1) ด้านรัฐ สังคม และสิ่งแวดล้อม, (2) ด้านผู้รับบริการและผู้มีส่วนได้ส่วนเสีย (เชื่อมระบบประเมินของ ป.ป.ช.), (3) ด้านองค์การ (บริหารความเสี่ยงและควบคุมภายใน) และ (4) ด้านผู้ปฏิบัติงาน (แผนพัฒนาบุคลากร Hard/Soft Skills)', 2, '513a2ff843de2d57...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1g9j-nLc3x_lCjAQXsCOv3IOMpUJDgm9B/view?usp=drivesdk');
INSERT INTO documents VALUES (93, 'TSRI-F07-00-007', 'TSRI-DOC-0093', 'TSRI-N093', 7, 'หมวดที่ 7', '6. ประกาศ อนก. เรื่อง นโยบายและแนวทางจัดการเรื่องร้องเรียน (ลงนาม).pdf', 'ประกาศคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายและแนวทางการจัดการเรื่องร้องเรียน สกสว. (4 หน้า)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1', 'B1, B2 (F5 ฝ่ายกฎหมาย / เลขานุการคณะกรรมการ)', 'อำนาจกำกับดูแลของคณะกรรมการอำนวยการ สกสว. ตามมาตรา 47 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 เชื่อมระเบียบวินัย พ.ศ. 2564 และระเบียบประมวลจริยธรรม พ.ศ. 2564', 'แบ่งระดับผู้มีอำนาจพิจารณาเรื่องร้องเรียนชัดเจน (หมวด 3 ข้อ 7–8): (1) กรณีร้องเรียนผู้บริหารหรือพนักงาน สกสว. ผู้มีอำนาจพิจารณาคือ ''ผู้อำนวยการ สกสว.''; (2) กรณีร้องเรียนกรรมการอำนวยการหรือผู้อำนวยการ สกสว. ผู้มีอำนาจพิจารณาคือ ''คณะกรรมการอำนวยการ สกสว.'' (ยื่นผ่านประธาน อนก.สกสว.) โดยตั้งคณะกรรมการตรวจสอบข้อเท็จจริงและคุ้มครองผู้แจ้งเบาะแส', 4, '7ef9a00b6730a375...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1qKM9bG1hc1-RnuXpGJO1c1ENq3bzZmCA/view?usp=drivesdk');
INSERT INTO documents VALUES (94, 'TSRI-F08-00-001', 'TSRI-DOC-0094', 'TSRI-N094', 8, 'หมวดที่ 8', 'คำสั่งที่ พด.70 2564 เรื่องมอบอำนาจดำเนินงานจัดซื้อจัดจ้าง.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ พด.70/2564 เรื่อง มอบอำนาจการดำเนินงานเกี่ยวกับการจัดซื้อจัดจ้างและการบริหารพัสดุ (สั่ง ณ วันที่ 19 มี.ค. 2564, ใช้บังคับ 22 มี.ค. 2564)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B3', 'B3, B1 (F5 ฝ่ายพัสดุ 5.2.1 & F2)', 'มาตรา 50(1) และ (2) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 16 แห่งข้อบังคับ อนก. การเงินฯ พ.ศ. 2563 และข้อ 7 แห่งระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560', 'มอบอำนาจอนุมัติจัดซื้อจัดจ้าง บริหารสัญญา และอนุมัติจำหน่ายพัสดุภายในวงเงินไม่เกิน 500,000 บาท โดยแยกชัดเจนระหว่าง: ข้อ 1 พัสดุของ ''สำนักงาน (สกสว.)'' ให้ผู้บริหารที่กำกับดูแลสำนักบริหารและพัฒนาองค์กร (F5) มีอำนาจอนุมัติ; และข้อ 2 พัสดุของ ''กองทุนส่งเสริม ววน.'' ให้ผู้บริหารที่กำกับดูแลสำนักบริหารงบประมาณ ววน. (F2) มีอำนาจอนุมัติ', 2, '37f454358bb00193...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1RzLinYfN-VbHheqcjX1zfo1dIJYagRbo/view?usp=drivesdk');
INSERT INTO documents VALUES (95, 'TSRI-F08-00-002', 'TSRI-DOC-0095', 'TSRI-N095', 8, 'หมวดที่ 8', 'คำสั่งที่ พด.71 2564 เรื่องแต่งตั้งเจ้าหน้าที่การจัดซื้อจัดจ้าง.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ พด.71/2564 เรื่อง แต่งตั้งหัวหน้าเจ้าหน้าที่และเจ้าหน้าที่เกี่ยวกับการจัดซื้อจัดจ้างและการบริหารพัสดุ (สั่ง ณ วันที่ 19 มี.ค. 2564)', 'ระดับที่ 2 (ก): กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ และคำสั่ง', 'B1, B3', 'B3, B1 (F5 ฝ่ายพัสดุ 5.2.1)', 'มาตรา 50(1) และ (2) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 16 แห่งข้อบังคับ อนก. การเงินฯ พ.ศ. 2563 และ พ.ร.บ.การจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560', 'แต่งตั้งหัวหน้าเจ้าหน้าที่พัสดุ (1 ราย) และเจ้าหน้าที่พัสดุหลัก (2 ราย) ของ สกสว. และกองทุนส่งเสริม ววน. และในข้อ 1(4) แต่งตั้งให้ผู้ปฏิบัติงานอื่นของ สกสว. เป็นเจ้าหน้าที่พัสดุสำหรับวงเงินจัดซื้อจัดจ้างไม่เกิน 10,000 บาท ตามความจำเป็นและเหมาะสมเพื่อความคล่องตัวในการปฏิบัติงาน', 2, 'cf5e6e599d72b188...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1vxsiHhK4xvvVi7-YlvyyYP0CEfuoPzA7/view?usp=drivesdk');
INSERT INTO documents VALUES (96, 'TSRI-F09-00-001', 'TSRI-DOC-0096', 'TSRI-N096', 9, 'หมวดที่ 9', '♥คู่มือการดำเนินการทางวินัย สกสว.pdf', 'คู่มือการดำเนินการทางวินัย พนักงานและลูกจ้างของสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม (สกสว.) พ.ศ. 2568 (กันยายน 2568, 111 หน้า)', 'ระดับที่ 2 (ข): คู่มือการปฏิบัติงานและกระบวนงานมาตรฐาน (SOP)', 'B2', 'B2 (F5 ฝ่ายกฎหมาย 5.3.3 & ฝ่ายทรัพยากรบุคคล 5.3.2)', 'เชื่อมโยง พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539 (ระดับที่ 3) เข้ากับข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563, ระเบียบ อนก. วินัยและการดำเนินการทางวินัย พ.ศ. 2564 และประกาศกองทุนสำรองเลี้ยงชีพ พ.ศ. 2564', 'วิเคราะห์องค์ประกอบความผิดวินัยครบทุกข้อ (ข้อ 7, 8, 9, 11, 13), ลำดับขั้นตอนตั้งแต่วินิจฉัยเบื้องต้น ตรวจสอบข้อเท็จจริง สืบสวน สอบสวนวินัยอย่างไม่ร้ายแรงและร้ายแรง การสั่งพักงาน การลงโทษ และการตัดสิทธิเงินสมทบกองทุนสำรองเลี้ยงชีพ พร้อมแบบพิมพ์คำสั่งและบันทึกมาตรฐาน 13 แบบ (แบบ วน.1 ถึง แบบ วน.8 และแบบสำนวนวินัย)', 111, '12889f7fd0775189...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1ynhZs2SR6CdVoStAOmaVGdhJk8AHVCnt/view?usp=drivesdk');
INSERT INTO documents VALUES (97, 'TSRI-F09-00-002', 'TSRI-DOC-0097', 'TSRI-N097', 9, 'หมวดที่ 9', 'คู่มือบริหารโครงการ ORG_update0766.pdf', 'คู่มือบริหารโครงการวิจัยเพื่อพัฒนาการปฏิบัติงานตามพันธกิจ (Operational Research Grant; ORG) (ปรับปรุง ก.ค. 2566, 50 หน้า)', 'ระดับที่ 2 (ข): คู่มือการปฏิบัติงานและกระบวนงานมาตรฐาน (SOP)', 'A5, B1', 'A5, B1, B3 (F5 ฝ่ายแผนและงบประมาณสำนักงาน / การเงิน & F1)', 'มาตรา 43 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบมาตรา 9 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (ข้อยกเว้นให้ สกสว. สนับสนุนงานวิจัยเพื่อพัฒนาการปฏิบัติงานตามหน้าที่และอำนาจของหน่วยงานได้) และมาตรา 4(1) แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'วางแนวทางบริหารโครงการ ORG ครบวงจร: เอกสารประกอบสัญญา 8 รายการ, การเปิดบัญชีโครงการ, การเบิกจ่าย 7 หมวดค่าใช้จ่าย (ค่าตอบแทน ค่าจ้าง ค่าวัสดุ ค่าใช้สอย ค่าครุภัณฑ์ ค่าใช้จ่ายอื่น ค่าบำรุงสถาบัน), การปรับแผน/ขยายเวลา, ทรัพย์สินทางปัญญา และแบบฟอร์มการเงิน/ครุภัณฑ์แนบท้าย 11 แบบ', 50, '0da83043e9d57033...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1DJ9KK15S6ELYJYpXTg-3AXWI-JD8NyS0/view?usp=drivesdk');
INSERT INTO documents VALUES (98, 'TSRI-F09-00-003', 'TSRI-DOC-0098', 'TSRI-N098', 9, 'หมวดที่ 9', 'คู่มือระเบียบการเงิน.pdf', 'คู่มือการปฏิบัติงาน และระเบียบปฏิบัติด้านการเงิน (ฉบับปรับปรุง 1 มิถุนายน 2568, 45 หน้า)', 'ระดับที่ 2 (ข): คู่มือการปฏิบัติงานและกระบวนงานมาตรฐาน (SOP)', 'B3, B4', 'B3, B4 (F5 ฝ่ายการเงิน 5.4.2 & ฝ่ายบัญชี 5.4.1)', 'บูรณาการข้อบังคับและระเบียบการเงินในหมวดที่ 6 (DOC-0079 ถึง 0086) และระเบียบ กสว. รับ-จ่ายเงินกองทุน (DOC-0005) เข้าสู่ขั้นตอนปฏิบัติงานของสำนักบริหารและพัฒนาองค์กร (F5)', 'สรุปตารางคำสั่งมอบอำนาจการอนุมัติจ่ายเงิน 3 กลุ่ม: (1) เงินสำนักงานและเงินกองทุน, (2) เงินโครงการวิจัยเพื่อพัฒนาการปฏิบัติงาน (ORG) และ (3) เงินโครงการวิจัยต่อเนื่องของ สกว. เดิมตามบทเฉพาะกาล ม.71 (Ongoing) พร้อมตารางอัตราค่าเบี้ยเลี้ยง ค่าที่พัก ค่ายานพาหนะในประเทศ/ต่างประเทศ และขั้นตอนตรวจใบสำคัญจ่าย', 45, '651ffaae3e386836...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1Ds0ZVoOHgfNkWNuHcvKLN2KVl_5Qc2BI/view?usp=drivesdk');
INSERT INTO documents VALUES (99, 'TSRI-F09-00-004', 'TSRI-DOC-0099', 'TSRI-N099', 9, 'หมวดที่ 9', '(Final) คู่มือจัดทำคำขอและการบริหารงบประมาณทุ.pdf', 'คู่มือการจัดทำคำของบประมาณและการบริหารจัดการงบประมาณเพื่อสนับสนุนงานมูลฐานตามพันธกิจของหน่วยรับงบประมาณ (Fundamental Fund; FF) (ฉบับสมบูรณ์, 180 หน้า)', 'ระดับที่ 2 (ข): คู่มือการปฏิบัติงานและกระบวนงานมาตรฐาน (SOP)', 'A2', 'A2, A5 (F2 สำนักกลยุทธ์งบประมาณฯ & F1)', 'มาตรา 41(4), (7) และมาตรา 44(6), (7) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562, มาตรา 17–18 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (แก้ไขเพิ่มเติม ฉ.2 พ.ศ. 2568) และประกาศ กสว. เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณฯ พ.ศ. 2566–2569', 'กำหนดคู่มือปฏิบัติการ 5 บทสำหรับหน่วยรับงบประมาณ FF: (1) หลักการจัดสรรงบแบบ Block Grant และการแบ่งกลุ่มหน่วยรับงบ/จุดมุ่งเน้น, (2) อัตราค่าใช้จ่าย 6 หมวด (รวมงบเสริมสร้างความเข้มแข็งและธรรมาภิบาล), (3) การทำคำรับรองฯ การปรับแผน และการคืนเงิน/ดอกเบี้ยผ่านระบบ NRIIS, (4) การติดตามประเมินผล และ (5) การจัดทำโครงการแบบผูกพันงบประมาณมากกว่า 1 ปี (Multi-year Promised Grant) สำหรับปีงบประมาณ พ.ศ. 2570', 180, 'd5d3ade39fee0cef...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/188ucymmUjrjyctBd5SRkzZkcpXil0Kf6/view?usp=drivesdk');
INSERT INTO documents VALUES (100, 'TSRI-F10-00-001', 'TSRI-DOC-0100', 'TSRI-N100', 10, 'หมวดที่ 10', '(Final) รายงานการประเมินผลสัมฤทธิ์ พรบ.การส่งเสริมการใช้ประโยชน์ฯ รวมภาคผนวก.pdf', 'รายงานวิจัยฉบับสมบูรณ์ โครงการประเมินผลสัมฤทธิ์ของพระราชบัญญัติการส่งเสริมวิทยาศาสตร์ การวิจัยและนวัตกรรม พ.ศ. 2562 รวมภาคผนวก (สัญญาเลขที่ ORG68F5006, 31 สิงหาคม 2568, 645 หน้า)', 'ระดับที่ 3: รายงานประเมินผลสัมฤทธิ์ตามรัฐธรรมนูญ มาตรา 77', 'A4, A5', 'A5, A1–A4, B1 (F1, F2, F3, F4, F5)', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย พ.ศ. 2560 มาตรา 77 และ พ.ร.บ.หลักเกณฑ์การจัดทำร่างกฎหมายและการประเมินผลสัมฤทธิ์ของกฎหมาย พ.ศ. 2562 ประกอบ พ.ร.บ.สภานโยบายฯ มาตรา 44(8) และ พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562', 'ประเมินผลสัมฤทธิ์ของการบังคับใช้กฎหมายหลังครบรอบ 5 ปี ครอบคลุม 8 มาตรการหลัก: (1) การกำหนดนโยบาย ยุทธศาสตร์และแผน ววน., (2) การจัดสรรงบประมาณ ววน., (3) การจัดซื้อจัดจ้างเพื่อการวิจัยและพัฒนา, (4) การส่งเสริมบุคลากร ววน., (5) การบริหารจัดการข้อมูล ววน. และบทกำหนดโทษ, (6) การใช้ประโยชน์ผลงานวิจัยและนวัตกรรม (เชื่อม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564), (7) มาตรฐานและจริยธรรมการวิจัย และ (8) การบูรณาการระหว่างหน่วยงาน พร้อมข้อเสนอแนะเชิงเศรษฐศาสตร์ (GII / World Competitiveness) และกฎหมาย', 645, '2fc6c36bf0a2632c...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1wpVqJ-_KNwHuN9X5q5eiOs_vgnHZwlsD/view?usp=drivesdk');
INSERT INTO documents VALUES (101, 'TSRI-F11-00-001', 'TSRI-DOC-0101', 'TSRI-N101', 11, 'หมวดที่ 11', 'standard-operating-procedure-for-sri-budget-allocation.pdf', 'กระบวนการทำงานที่เป็นมาตรฐาน (Standard Operating Procedure; SOP) ในการบริหารจัดการระบบวิทยาศาสตร์ วิจัยและนวัตกรรม (ววน.) ในภาพรวมกระบวนการจัดสรรงบประมาณ (กันยายน 2569, 13 หน้า)', 'ระดับที่ 2 (ข): คู่มือการปฏิบัติงานและกระบวนงานมาตรฐาน (SOP)', 'A1, A2, A5', 'A2 (หลัก), A1, A5 (F2 & F1)', 'มาตรา 11(2), มาตรา 12(2), มาตรา 41(2),(4),(7) และมาตรา 44(4),(5),(6),(7) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบมาตรา 17(2) แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562', 'กำหนดผังกระบวนงาน (Process Flow) และกรอบเวลาปฏิบัติงานจริงตามปฏิทินงบประมาณล่วงหน้า 2 ปี (ปี T ถึง T+2): (1) ก.ค.–ส.ค.(T) จัดทำกรอบวงเงินและทบทวนหลักเกณฑ์เสนอ กสว., (2) ก.ย.–ต.ค.(T->T+1, ~45 วัน) เปิดรับคำขอผ่านระบบ NRIIS (FF/SF) และ STARS (ST), (3) ต.ค.–พ.ย.(T+1, ~20 วัน) สกสว. กลั่นกรองคำขอ, (4) ธ.ค.–ม.ค.(T+1) เสนอ กสว. และ คกก.พิจารณางบประมาณ ม.12(2) และ Sign-off E-budgeting ส่งสำนักงบประมาณ, (5) เม.ย.–พ.ค.(T+1) จัดสรรขั้น Pre-ceiling ให้หน่วยงานปรับคำชี้แจงใน 15 วัน และตรวจใน 10 วัน, (6) มิ.ย.–ส.ค.(T+1) ชี้แจง กมธ.งบประมาณ ปรับยอดตามมติ กมธ. และแจ้งจัดสรรเพื่อทำคำรับรองฯ (พร้อม SOP ย่อย 1.1–1.3 และ 2.1–2.3)', 13, 'b63206948cd52edc...', 'ใช้งานจริง (Active)', 1, 'https://drive.google.com/file/d/1LxbDcP0gTJxnqMI_d5f4ayWKJ9hOIVA1/view?usp=drivesdk');
INSERT INTO crosslist_items VALUES ('CL-01', 'A1 (การจัดทำแผน ววน.)', 'สำนัก F1 (สำนักยุทธศาสตร์ฯ) / P01–P02', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.44(3), 41(1), 11(1) (TSRI-F01-01-001) ↔ พ.ร.บ.ส่งเสริม ววน. ม.6, 12(1)–(6), 13–15 (TSRI-F02-01-001)
INSERT INTO crosslist_items VALUES ('CL-02', 'A2 (การตั้งงบประมาณและกลั่นกรองคำขอ FF/SF)', 'สำนัก F1 & F2 / P03–P06', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.44(4)–(7), 41(2)–(5), 12(2) และ ฉ.2 พ.ศ. 2568 แก้ ม.12(1) (TSRI-F01-01-001, 002) ↔ พ.ร.บ.ส่งเสริม ววน. ม.16, 17(1)–(2)
INSERT INTO crosslist_items VALUES ('CL-03', 'A2 (การจัดสรรงบปลายน้ำและคำรับรอง Multi-year ม.18)', 'สำนัก F2 & F5 / P06–P07', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.41(7), 57(1) ↔ พ.ร.บ.ส่งเสริม ววน. (ฉ.2) พ.ศ. 2568 แก้ ม.18 (TSRI-F02-01-002)
INSERT INTO crosslist_items VALUES ('CL-04', 'B1 / A2 (ขอบเขตการทำวิจัยเองของ สกสว. ทุน ORG)', 'ทุกสำนัก (F1–F5, IU1–IU6) / P05, P23', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.43 วรรคสอง (ห้ามแข่งขันกับหน่วยรับงบ) ↔ พ.ร.บ.ส่งเสริม ววน. ม.7(1),(2) และ ม.9 วรรคหนึ่ง
INSERT INTO crosslist_items VALUES ('CL-05', 'A3 (การพัฒนากองทุน การหาผลประโยชน์ และการแยก 2 บัญชี)', 'สำนัก F3 & F5 / P10–P12, P25', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.45 (เงินและทรัพย์สินสำนักงาน) vs ม.54–59 (เงินและทรัพย์สินกองทุน ววน.)
INSERT INTO crosslist_items VALUES ('CL-06', 'A3 (การกำกับดูแล PMU และการใช้จ่ายเงินอุดหนุนของหน่วยบริหารทุน)', 'สำนัก F3 & F1 / P08–P12', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.41(8),(9),(13) ↔ พ.ร.บ.ส่งเสริม ววน. ม.7(2), 8, 9 (TSRI-F02-01-001)
INSERT INTO crosslist_items VALUES ('CL-07', 'A4 (การสร้างความร่วมมือต่างประเทศและการรับทุนต่างชาติ)', 'สำนัก F4 (สำนักขับเคลื่อนฯ) / P13–P14, P17', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.44(13) + ม.45(3),(4) + ม.55(3),(4) ↔ พ.ร.บ.ส่งเสริม ววน. ม.5(4), 11(6)
INSERT INTO crosslist_items VALUES ('CL-08', 'A4 (การขับเคลื่อนการใช้ประโยชน์ผลงานวิจัย TRIUP และรางวัล TBIR)', 'สำนัก F4 / P15–P18', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.44(11), 41(11), 54(4) ↔ พ.ร.บ.ส่งเสริม ววน. ม.28–31 ↔ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 (TRIUP Act) (TSRI-F03-01-001)
INSERT INTO crosslist_items VALUES ('CL-09', 'A5 (ระบบฐานข้อมูลกลาง NRIIS มาตรฐานการวิจัย และโทษอาญา ม.36)', 'สำนัก F1 & หน่วยภารกิจ IU1 / P10, P19–P20', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.41(10),(14), 44(12),(14), 64–65 ↔ พ.ร.บ.ส่งเสริม ววน. ม.15, 22–27, 32–33 และบทกำหนดโทษอาญา ม.36 (จำคุกไม่เกิน 5 ปี / ปรับไม่เกิน 100,000 บาท)
INSERT INTO crosslist_items VALUES ('CL-10', 'B1 (โครงสร้างองค์กร 4 เสาหลัก อำนาจสั่งการ และการมอบอำนาจปี 2569)', 'สำนัก F5 (สำนักบริหารและพัฒนาองค์กร) / P21, P23', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.40–50 (ม.47 อนุโลม ม.25–27 อำนาจ อนก., ม.49 อนุโลม ม.29–33, 35–36 อำนาจ ผอ.)
INSERT INTO crosslist_items VALUES ('CL-11', 'B2 (การบริหารงานบุคคล โครงสร้างตำแหน่งปี 2569 สวัสดิการ และวินัย)', 'สำนัก F5 (ฝ่ายบริหารทรัพยากรบุคคล) / P24', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.43 วรรคสาม (ไม่ใช่ข้าราชการ), ม.47→25(4), ม.50(3)–(5)
INSERT INTO crosslist_items VALUES ('CL-12', 'B3 (การเงินการคลังสำนักงาน พัสดุวิจัย ม.19 และคำสั่งมอบอำนาจ พด.70–71/2564)', 'สำนัก F5 (ฝ่ายการเงิน/พัสดุ) & F2 / P25', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.45, 47→25(4)(ฉ)(ช) ↔ พ.ร.บ.ส่งเสริม ววน. ม.19 (พัสดุวิจัย) ↔ พ.ร.บ.จัดซื้อจัดจ้างฯ 2560
INSERT INTO crosslist_items VALUES ('CL-13', 'B4 (การบัญชี การตรวจสอบภายใน IA และรายงานประจำปี 2 เส้นทางคู่ขนาน)', 'สำนัก F5 & หน่วยตรวจสอบภายใน (IA) / P25–P27', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.51→38–39 (งบสำนักงานส่งผู้สอบบัญชีใน 90 วัน), ม.52 (รายงานประจำปีสำนักงาน) vs ม.60–63 (งบกองทุนส่ง สตง. ใน 180 วัน & คกก.ตรวจสอบ) vs ม.44(14) (รายงานกองทุน) ↔ พ.ร.บ.วินัยการเงินการคลังฯ 2561 ม.79
INSERT INTO crosslist_items VALUES ('CL-14', 'บทเฉพาะกาล (การบริหารสัญญารับโอน สกว. อดีต–ปัจจุบัน–อนาคต)', 'สำนัก F5 & F1 / P10, P25', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.66–80 (โดยเฉพาะ ม.71, 74–76, 80) ↔ พ.ร.บ.ส่งเสริม ววน. ม.37–39
INSERT INTO crosslist_items VALUES ('CL-15', 'A5 / A1 (การประเมินผลสัมฤทธิ์ของกฎหมายตามรัฐธรรมนูญ มาตรา 77)', 'สำนัก F1 & F5 / P01, P19, P23', 'ระดับที่ 1: รัฐธรรมนูญ มาตรา 77 & พ.ร.บ.หลักเกณฑ์การจัดทำร่างกฎหมายและการประเมินผลสัมฤทธิ์ของกฎหมาย พ.ศ. 2562
INSERT INTO interview_questions VALUES ('Q01 (PROC)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'ทุกกลุ่ม (เน้น 4.2.2 & 4.2.3)', 'ในกระบวนงานที่ท่านรับผิดชอบ ขั้นตอนเริ่มต้นจนถึงสิ้นสุดมีกี่ขั้นตอนหลัก และแต่ละขั้นตอนอ้างอิงระเบียบ ประกาศ คู่มือ หรือ SOP ฉบับใดเป็นฐานในการปฏิบัติงาน?', 'เชื่อมโยงคลังข้อมูลทั้ง 11 หมวด (TSRI-DOC-0001 ถึง 0101) โดยเฉพาะหมวด 9 คู่มือ (4 เล่ม) และหมวด 11 SOP จัดสรรงบ (DOC-0101)', 'D1 (ข้อกำหนดกฎหมาย), D2 (กฎรอง/SOP), D4 (การปฏิบัติจริง)', '• C1: มีคู่มือ/SOP ครอบคลุมครบทุกขั้นตอนหรือไม่
INSERT INTO interview_questions VALUES ('Q02 (AUTH)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'ทุกกลุ่ม (4.2.1, 4.2.2, 4.2.3)', 'ใครคือผู้มีอำนาจอนุมัติหรือให้ความเห็นชอบในขั้นตอนสุดท้ายของงานนี้ และใช้อำนาจตามมาตราใดของ พ.ร.บ. หรือตามคำสั่งมอบอำนาจฉบับใด (เช่น คำสั่ง พด.70/2564 หรือ พด.71/2564)?', 'พ.ร.บ.สภานโยบายฯ ม.44 (กสว.), ม.47 (อนก.), ม.50 (ผอ.สกสว.) และคำสั่งมอบอำนาจหมวด 4 (DOC-0053–60) & หมวด 8 (DOC-0094–95)', 'D1 (ฐานอำนาจ), D2 (คำสั่งมอบอำนาจ), D5 (ลายมือชื่อในเอกสารอนุมัติ)', '• C1: มีคำสั่งมอบอำนาจเป็นหนังสือชัดเจนหรือไม่
INSERT INTO interview_questions VALUES ('Q03 (ROLE)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.1 & 4.2.2', 'ในงานที่มีจุดตัดระหว่างสำนักหรือระหว่างคณะกรรมการ (กสว. vs อนก.สกสว.) มีการแบ่งแยกบทบาทหน้าที่ผู้เสนอ ผู้กลั่นกรอง และผู้อนุมัติอย่างไรเพื่อไม่ให้เกิดการก้าวล่วงอำนาจ?', 'พ.ร.บ.สภานโยบายฯ ม.44 vs ม.47 vs ม.50 และประกาศแบ่งส่วนงาน สกสว. พ.ศ. 2569 (TSRI-F04-00-012 / DOC-0063)', 'D1 (โครงสร้างอำนาจ 4 เสาหลัก), D2 (ประกาศแบ่งส่วนงานปี 2569), D4 (การชงเรื่องเข้าบอร์ด)', '• C1: วาระการประชุมระบุฐานอำนาจของคณะกรรมการถูกต้องหรือไม่
INSERT INTO interview_questions VALUES ('Q04 (COND)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'เงื่อนไขบังคับก่อน (Pre-conditions) ที่ต้องตรวจสอบให้ครบถ้วนก่อนอนุมัติหรือจัดสรรงบประมาณ/ทำคำรับรอง/เบิกจ่าย มีอะไรบ้าง และมี Checklist ตรวจสอบหรือไม่?', 'พ.ร.บ.ส่งเสริม ววน. ม.12, 17, 18 (ฉ.2 พ.ศ. 2568), ประกาศคำของบ >50 ข้อ (DOC-0007–0013) และคู่มือคำของบ FF (DOC-0099)', 'D1 (เงื่อนไขตามกฎหมาย), D2 (Checklist ตามคู่มือ), D5 (ใบตรวจรับ/แบบคำรับรองในแฟ้ม)', '• C1: มีแบบตรวจสอบเงื่อนไขครบทุกข้อตามประกาศ กสว. หรือไม่
INSERT INTO interview_questions VALUES ('Q05 (EXCEPT)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'ทุกกลุ่ม (4.2.1, 4.2.2, 4.2.3)', 'ข้อห้ามหรือข้อยกเว้นตามกฎหมายในงานของท่านมีอะไรบ้าง (เช่น ห้าม สกสว. ทำวิจัยแข่งขันกับหน่วยรับงบตาม ม.43 วรรคสอง หรือข้อยกเว้นการยึดเป็นเจ้าของผลงานตาม TRIUP ม.8) และมีวิธีคัดกรองอย่างไร?', 'พ.ร.บ.สภานโยบายฯ ม.43 วรรคสอง, พ.ร.บ.ส่งเสริม ววน. ม.9, พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ (TRIUP) ม.7–8 และคู่มือทุน ORG (DOC-0097)', 'D1 (บทบัญญัติข้อห้าม/ข้อยกเว้น), D3 (ความเข้าใจผู้ปฏิบัติ), D4 (การคัดกรองจริง)', '• C1: คู่มือ ORG และคู่มือ TRIUP ระบุเกณฑ์ข้อยกเว้นชัดเจนหรือไม่
INSERT INTO interview_questions VALUES ('Q06 (BALANCE)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.1 & 4.2.2 (รวม IA)', 'มีกลไกการตรวจสอบถ่วงดุล (Check & Balance) หรือการสอบทานความถูกต้องโดยหน่วยงานอิสระ (เช่น หน่วยตรวจสอบภายใน IA คณะกรรมการตรวจสอบ หรือคณะกรรมการประเมินอิสระ ม.64) ในขั้นตอนใดบ้าง?', 'พ.ร.บ.สภานโยบายฯ ม.60–65, ข้อบังคับการเงินและบัญชี 2563 (DOC-0079), ระเบียบการเงิน 2563 (DOC-0080)', 'D1 (กลไกถ่วงดุลตามกฎหมาย), D2 (กฎบัตร/ระเบียบการเงิน), D5 (รายงานผลการตรวจสอบ IA/สตง.)', '• C1: มีกลไกถ่วงดุลครบตามที่ พ.ร.บ. กำหนดหรือไม่
INSERT INTO interview_questions VALUES ('Q07 (KNOW)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'ในการปฏิบัติงานรายวัน ท่านใช้เอกสารฉบับใดเป็นคู่มืออ้างอิงหลัก และมีประเด็นข้อกฎหมายหรือระเบียบใดที่บุคลากรยังสับสนหรือตีความไม่ตรงกัน?', 'เชื่อมโยงหมวดที่ 9 คู่มือการดำเนินงาน 4 เล่ม (DOC-0096 ถึง 0099) และหมวดที่ 11 SOP (DOC-0101) สู่การออกแบบสื่อระยะที่ 4', 'D2 (คู่มือ/SOP), D3 (ความเข้าใจของผู้ปฏิบัติงาน)', '• C1: มีคู่มือที่อัปเดตเป็นปัจจุบัน (สะท้อน พ.ร.บ. ฉ.2 พ.ศ. 2568 และโครงสร้างปี 2569) หรือไม่
INSERT INTO interview_questions VALUES ('Q08 (EVID)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'หลักฐานเชิงประจักษ์ (Empirical Evidence) ที่ใช้พิสูจน์ว่าได้ปฏิบัติตามกฎหมายในขั้นตอนนี้คือเอกสารหรือข้อมูลดิจิทัลใด (เช่น บันทึกใน NRIIS/STARS, คำรับรอง ม.18, ใบสำคัญจ่าย, รายงานประชุม) และจัดเก็บไว้ที่ใด?', 'ครอบคลุมทั้ง 9 Clusters และห่วงโซ่หลักฐาน CHAIN-01 ถึง CHAIN-06', 'D4 (การปฏิบัติจริง), D5 (หลักฐานเชิงประจักษ์ในแฟ้ม/ระบบ)', '• C1: มีการจัดเก็บหลักฐานครบตามรายการที่ระเบียบกำหนดหรือไม่
INSERT INTO interview_questions VALUES ('Q09 (TIME)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'งานของท่านมีกรอบเวลาบังคับตามกฎหมายหรือระเบียบหรือไม่ (เช่น คืนเงิน PMU ใน 45 วัน, ปิดงบสำนักงาน 90 วัน / กองทุน 180 วัน, กลั่นกรองคำของบ 20 วัน, แจ้งผลงาน TRIUP) และสามารถทำได้ทันตามกำหนดหรือไม่?', 'ม.51→39 (90 วัน), ม.61 (180 วัน), ประกาศ PMU (45 วัน), ระเบียบชดใช้ทุน สกว. (เตือน 30 วัน / บอกเลิก 15 วัน), SOP งบ (45/20/20/15/10 วัน)', 'D1/D2 (กรอบเวลามาตรฐาน), D4/D5 (วันเวลาที่บันทึกจริงในระบบ/รับ-ส่งหนังสือ)', '• C1: มีปฏิทินควบคุมกำหนดเวลา (SLA / Deadline Alert) หรือไม่
INSERT INTO interview_questions VALUES ('Q10 (TRANS)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'เมื่อมีการแก้ไขกฎหมายหรือเปลี่ยนโครงสร้าง/ระเบียบใหม่ (เช่น พ.ร.บ. ฉ.2 พ.ศ. 2568, โครงสร้างส่วนงานปี 2569, หรือสัญญารับโอนจาก สกว.) ท่านมีวิธีตรวจสอบการบังคับใช้ตาม ''วันที่เกิดเหตุ'' อย่างไร?', 'บทเฉพาะกาล พ.ร.บ.สภานโยบายฯ ม.66–80, ระเบียบชดใช้ทุน สกว. 2564 (DOC-0005), ประกาศแบ่งส่วนงานปี 2569 (DOC-0063)', 'D1/D2 (บทเฉพาะกาลและวันบังคับใช้), D3 (การเลือกใช้เกณฑ์ตามวันเกิดเหตุ), D5 (บันทึกการพิจารณา)', '• C1: มีตารางเทียบเคียงเกณฑ์เก่า–เกณฑ์ใหม่ตามช่วงเวลาหรือไม่
INSERT INTO interview_questions VALUES ('Q11 (M77)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.1 & 4.2.2', 'จากรายงานการประเมินผลสัมฤทธิ์ของกฎหมายตามรัฐธรรมนูญ มาตรา 77 (645 หน้า) ใน 8 มาตรการหลัก สำนักของท่านได้นำข้อค้นพบไปปรับปรุงหลักเกณฑ์หรือกระบวนงานใดแล้วบ้าง?', 'หมวดที่ 10 รายงานการประเมินผลสัมฤทธิ์ พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (TSRI-F10-00-001 / DOC-0100)', 'D1 (รัฐธรรมนูญ ม.77), D2 (การปรับแก้กฎรอง), D4 (การขับเคลื่อนหลังประเมิน)', '• C1: มีแผนขับเคลื่อนข้อเสนอแนะทั้ง 8 มาตรการหรือไม่
INSERT INTO interview_questions VALUES ('Q12 (VALID)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'ทุกกลุ่ม (4.2.1, 4.2.2, 4.2.3)', 'หากต้องจัดลำดับความสำคัญในการปรับปรุงกฎระเบียบ คู่มือ หรือพัฒนาระบบสื่อการเรียนรู้และคลังข้อสอบวัดสมรรถนะในระยะที่ 4 เรื่องใดคือ 3 อันดับแรกที่จำเป็นที่สุดสำหรับหน่วยงานของท่าน?', 'เชื่อมโยงผลการประเมิน C1 / C2 / A สู่การออกแบบคัมภีร์กฎหมาย 2 ฉบับ อินโฟกราฟิก 8 ชิ้น คลิป 15 คลิป และข้อสอบ 12 ชุด', 'D3 (ความต้องการพัฒนาสมรรถนะ), D4 (ข้อเสนอแนะเชิงปฏิบัติการ)', '• C1: ระบุหัวข้อกฎระเบียบและขั้นตอนที่ต้องการสื่อการเรียนรู้ได้ชัดเจน
INSERT INTO interview_questions VALUES ('QH01', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'คณะกรรมการ (กสว./อนก.) และผู้บริหารองค์กร (N=13)', '[ธรรมาภิบาล 4 เสาหลัก] ท่านมองว่าการแบ่งขอบเขตอำนาจระหว่าง สภานโยบายฯ, กสว. (ม.44), อนก.สกสว. (ม.47) และผู้อำนวยการ สกสว. (ม.50) ในทางปฏิบัติมีความชัดเจนเพียงใด และมีจุดใดที่เกิดการทับซ้อนหรือช่องว่างในการตัดสินใจ?', 'พ.ร.บ.สภานโยบายฯ ม.11, 44, 47, 50 และประกาศแบ่งส่วนงานปี 2569 (TSRI-F04-00-012)', 'D1, D2, D4 (Governance & Authority Alignment)', 'ประเมิน C1 (ความครบถ้วนของกรอบอำนาจ), C2 (การไม่ก้าวล่วงอำนาจระหว่างบอร์ด) และ A (ความคล่องตัวเชิงธรรมาภิบาล)', 'เชื่อมโยง CL-10 (Cluster B1) และคลิปที่ 1, 11');
INSERT INTO interview_questions VALUES ('QH02', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'กสว. / ผู้บริหารกำกับสำนัก F1', '[การจัดทำแผน ววน.] กระบวนการจัดทำแผนด้าน ววน. ให้ครบ 6 องค์ประกอบตาม ม.12 และการรับฟังความเห็นตาม ม.13 สามารถชี้นำการจัดสรรงบประมาณของประเทศได้จริงเพียงใด และผลประเมิน ม.77 สะท้อนจุดที่ต้องปรับปรุงอย่างไร?', 'พ.ร.บ.สภานโยบายฯ ม.44(3) ↔ พ.ร.บ.ส่งเสริม ววน. ม.6, 12–15 ↔ รายงาน ม.77 (TSRI-F10-00-001)', 'D1, D4, D5 (Strategic Alignment)', 'ประเมิน C1 (องค์ประกอบแผน 6 ด้าน), C2 (ขั้นตอนการเสนอเห็นชอบ) และ A (การเชื่อมโยงแผนสู่งบประมาณ)', 'เชื่อมโยง CL-01 & CL-15 (Cluster A1/A5) และคลิปที่ 1, 2');
INSERT INTO interview_questions VALUES ('QH03', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'คกก.งบประมาณ ม.12(2) / ผู้บริหารกำกับสำนัก F1–F2', '[งบประมาณต้นน้ำ 2 สาย] การกลั่นกรองคำของบประมาณระบบ ววน. ตามวงจรล่วงหน้า 2 ปี (ปี T ถึง T+2) และการแยกช่องทางหน่วยรับงบ ววน. กับส่วนราชการตาม ม.17 มีความท้าทายเชิงระบบอย่างไรหลังการแก้ไข พ.ร.บ. ฉบับที่ 2 พ.ศ. 2568?', 'พ.ร.บ.สภานโยบายฯ (ฉ.2) พ.ศ. 2568 แก้ ม.12(1) ↔ พ.ร.บ.ส่งเสริม ววน. ม.16–17 ↔ SOP จัดสรรงบ (DOC-0101)', 'D1, D2, D4 (Upstream Budget Governance)', 'ประเมิน C1 (เกณฑ์คำของบ >50 ข้อ), C2 (กรอบเวลาและองค์กรกลั่นกรอง) และ A (การบูรณาการกับสำนักงบประมาณ)', 'เชื่อมโยง CL-02 (Cluster A2) และคลิปที่ 3, 5');
INSERT INTO interview_questions VALUES ('QH04', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'กสว. / ผู้บริหารกำกับสำนัก F2', '[การจัดสรรปลายน้ำและคำรับรอง ม.18] การเปลี่ยนจากระบบสัญญารายโครงการมาสู่ ''คำรับรองการจัดสรรงบประมาณ'' และการตั้งงบผูกพันข้ามปี (Multi-year Promised Grant) ตาม ม.18 ที่แก้ไขใหม่ ช่วยปลดล็อกคอขวดของหน่วยรับงบได้เพียงใด?', 'พ.ร.บ.ส่งเสริม ววน. (ฉ.2) พ.ศ. 2568 แก้ ม.18 (TSRI-F02-01-002) & ประกาศคำของบ ฉ.3 พ.ศ. 2569 (DOC-0011)', 'D1, D2, D4, D5 (Downstream Allocation & Multi-year Grant)', 'ประเมิน C1 (แบบคำรับรองและเกณฑ์ 50:50), C2 (การอนุมัติโดย กสว. ก่อนแจ้งจัดสรร) และ A (ความคล่องตัวของหน่วยรับงบ)', 'เชื่อมโยง CL-03 (Cluster A2) และคลิปที่ 5');
INSERT INTO interview_questions VALUES ('QH05', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'ผู้อำนวยการ สกสว. / ผู้บริหารกำกับสำนัก F1–F5', '[ขอบเขตการทำวิจัยเองของ สกสว.] สกสว. มีนโยบายและเกณฑ์กำกับดูแลโครงการวิจัยภายใน (ทุน ORG) อย่างไรเพื่อให้มั่นใจว่าเป็นไปเพื่อพัฒนางานนโยบายของ สกสว. ตาม ม.9 และไม่แข่งขันกับหน่วยรับงบตาม ม.43 วรรคสอง?', 'พ.ร.บ.สภานโยบายฯ ม.43 วรรคสอง ↔ พ.ร.บ.ส่งเสริม ววน. ม.7, 9 ↔ คู่มือบริหารโครงการ ORG (DOC-0097)', 'D1, D2, D4 (Internal Research Boundary)', 'ประเมิน C1 (คู่มือ ORG 50 หน้า), C2 (การไม่ทำวิจัยแข่งขันกับหน่วยรับงบ) และ A (การนำผลวิจัย ORG ไปใช้ประโยชน์จริง)', 'เชื่อมโยง CL-04 (Cluster B1/A2) และคลิปที่ 4');
INSERT INTO interview_questions VALUES ('QH06', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'กสว. / ผู้บริหารกำกับสำนัก F3 & F5', '[การพัฒนากองทุนและกำกับ PMU] กลไกการนำเงินกองทุนไปหาผลประโยชน์ การแยกบัญชีเงินกองทุน (ม.55) ออกจากเงินสำนักงาน (ม.45) และการกำกับดูแลการใช้จ่ายเงินอุดหนุนของ PMU (รวมถึงการคืนเงินใน 45 วัน) มีความรัดกุมเพียงใด?', 'ม.45 vs ม.54–59, ระเบียบบริหารกองทุน (DOC-0003), ประกาศหาผลประโยชน์ (DOC-0015), ประกาศ PMU ฉ.1–3 (DOC-0016–18)', 'D1, D2, D4, D5 (Fund Development & PMU Governance)', 'ประเมิน C1 (เกณฑ์หาผลประโยชน์และประกาศ PMU), C2 (การแยก 2 บัญชีและการคืนเงิน 45 วัน) และ A (ประสิทธิภาพการบริหารกองทุน)', 'เชื่อมโยง CL-05 & CL-06 (Cluster A3) และคลิปที่ 6, 7');
INSERT INTO interview_questions VALUES ('QH07', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'กสว. / ผู้บริหารกำกับสำนัก F4', '[การขับเคลื่อนการใช้ประโยชน์ TRIUP และความร่วมมือ] การบังคับใช้ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยฯ พ.ศ. 2564 (และกฎรอง 14 ฉบับ) รวมถึงการทำความตกลงความร่วมมือต่างประเทศ สามารถผลักดันผลงานวิจัยสู่ภาคเศรษฐกิจและสังคมได้ตามเป้าหมายหรือไม่?', 'หมวดที่ 3 พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ 2564 และกฎรองรวม 15 ไฟล์ (DOC-0037–0051) & ประกาศความร่วมมือ 2566 (DOC-0020)', 'D1, D2, D4 (Research Utilization & International Cooperation)', 'ประเมิน C1 (ความครบถ้วนของกฎรอง TRIUP 14 ฉบับ), C2 (การให้ผู้รับทุนเป็นเจ้าของผลงานตามเงื่อนไข) และ A (แรงจูงใจในการนำผลงานไปใช้ประโยชน์)', 'เชื่อมโยง CL-07 & CL-08 (Cluster A4) และคลิปที่ 8, 9');
INSERT INTO interview_questions VALUES ('QH08', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'คกก.ติดตามประเมินผล / ผู้บริหารกำกับสำนัก F1 & IU1', '[ฐานข้อมูลกลาง NRIIS และการประเมินผล] ระบบฐานข้อมูลกลาง (NRIIS) มีมาตรการคุ้มครองความลับตาม ม.24–25 (ซึ่งมีโทษอาญาตาม ม.36) และการเชื่อมโยงข้อมูลเพื่อใช้ประเมินผลสัมฤทธิ์ตาม ม.64–65 และ ม.77 อย่างไร?', 'พ.ร.บ.สภานโยบายฯ ม.64–65 ↔ พ.ร.บ.ส่งเสริม ววน. ม.22–27, 36 ↔ ระเบียบข้อมูล ววน. (DOC-0028, 0031)', 'D1, D2, D4, D5 (Data Governance & M&E)', 'ประเมิน C1 (ระเบียบฐานข้อมูลและชั้นความลับ), C2 (การรักษาความลับและส่งข้อมูลครบถ้วน) และ A (คุณภาพข้อมูลเพื่อการตัดสินใจ)', 'เชื่อมโยง CL-09 & CL-15 (Cluster A5) และคลิปที่ 10');
INSERT INTO interview_questions VALUES ('QH09', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'อนก.สกสว. / ผู้อำนวยการ สกสว. / ผู้บริหารกำกับสำนัก F5', '[โครงสร้างปี 2569 บริหารบุคคล และจริยธรรม] การปรับโครงสร้างส่วนงานและบัญชีเงินเดือนใหม่ พ.ศ. 2569 (Level 1–8 / 1A–8A) ควบคู่กับข้อบังคับบุคคล วินัย และประมวลจริยธรรม (No Gift Policy) ช่วยเสริมสร้างสมรรถนะและธรรมาภิบาลของบุคลากรอย่างไร?', 'หมวดที่ 4 โครงสร้างปี 2569 (DOC-0061–64), หมวดที่ 5 บุคคล (DOC-0066–78), หมวดที่ 7 จริยธรรม (DOC-0087–93) & คู่มือวินัย (DOC-0096)', 'D1, D2, D4 (Organization, HR & Ethics Governance)', 'ประเมิน C1 (ความครบถ้วนของระเบียบปี 2569 และคู่มือวินัย), C2 (การปฏิบัติตามขั้นตอนสรรหา/ประเมิน/วินัย) และ A (ความเหมาะสมของโครงสร้างอัตราเงินเดือนและสวัสดิการ)', 'เชื่อมโยง CL-10 & CL-11 (Cluster B1/B2) และคลิปที่ 11, 12');
INSERT INTO interview_questions VALUES ('QH10', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'คกก.ตรวจสอบ / ผู้บริหารกำกับสำนัก F5 / หัวหน้าหน่วย IA', '[การเงิน พัสดุ และการตรวจสอบภายใน] กลไกการควบคุมภายในสำหรับคำสั่งมอบอำนาจพัสดุ (พด.70–71/2564) การปิดบัญชีคู่ขนาน (สำนักงาน 90 วัน vs กองทุน 180 วัน) และการบริหารสัญญารับโอนจาก สกว. มีความเสี่ยงใดที่ต้องเฝ้าระวังเป็นพิเศษ?', 'ม.51→38–39 (90 วัน), ม.60–63 (180 วัน), หมวด 6 การเงิน (DOC-0079–86), หมวด 8 พัสดุ (DOC-0094–95), คู่มือการเงิน (DOC-0098), ระเบียบชดใช้ทุน สกว. (DOC-0005)', 'D1, D2, D4, D5 (Financial Control, Procurement & Internal Audit)', 'ประเมิน C1 (คู่มือการเงินและตารางมอบอำนาจ), C2 (การอนุมัติถูกสายเงินและการส่งงบการเงินทัน 90/180 วัน) และ A (ประสิทธิภาพการควบคุมภายใน)', 'เชื่อมโยง CL-12, CL-13 & CL-14 (Cluster B3/B4) และคลิปที่ 13, 14, 15');
INSERT INTO interview_questions VALUES ('QO01', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F1 (P01–P02)', '[Walkthrough การจัดทำแผน ววน.] ขอเดินตามเอกสารจริงในการจัดทำ/ทบทวนแผนด้าน ววน.: ตรวจสอบว่ามีการรวบรวมข้อมูลครบ 6 องค์ประกอบตาม ม.12(1)–(6) บันทึกการรับฟังความเห็นตาม ม.13 และมติเห็นชอบตามลำดับขั้นอย่างไร?', 'พ.ร.บ.ส่งเสริม ววน. ม.12–15 (TSRI-F02-01-001) & รายงานประเมิน ม.77 (TSRI-F10-00-001)', 'D2, D3, D4, D5 (ตรวจแฟ้มแผน ววน. และรายงานการรับฟังความเห็น)', 'ตรวจรายการหลักฐานเทียบ Checklist ม.12(1)–(6) และบันทึกเวลาการเสนอเรื่อง', 'เชื่อมโยง CASE-A1-01 และ CHAIN-01');
INSERT INTO interview_questions VALUES ('QO02', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F1 & F2 (P03–P05)', '[Walkthrough คำของบและการคัดแยก FF/SF] ขอเดินตามเอกสารจริงในระบบ NRIIS/STARS: เมื่อหน่วยรับงบยื่นคำขอภายใน 45 วัน เจ้าหน้าที่ใช้ Checklist ใดตรวจเงื่อนไขตามประกาศ กสว. (>50 ข้อ) และคัดแยกคำขอ FF (8 โปรแกรม) กับ SF อย่างไร?', 'ประกาศ กสว. หลักเกณฑ์คำของบ 7 ฉบับ (DOC-0007–0013), คู่มือคำของบ FF 180 หน้า (DOC-0099) & SOP จัดสรรงบ (DOC-0101)', 'D2, D3, D4, D5 (ตรวจบันทึกการกลั่นกรองใน NRIIS/STARS กรอบ 20+20 วัน)', 'ตรวจความครบถ้วนของแบบตรวจคัดกรองและการปฏิบัติตามกรอบเวลาใน SOP', 'เชื่อมโยง CASE-A2-01, CHAIN-01 และคลิปที่ 3, 4');
INSERT INTO interview_questions VALUES ('QO03', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F2 (P06–P07)', '[Walkthrough การจัดสรร Pre-ceiling และคำรับรอง ม.18] ขอเดินตามเอกสารจริงตั้งแต่แจ้งยอด Pre-ceiling (ปรับใน 15 วัน ตรวจใน 10 วัน) การปรับตามมติ กมธ.งบประมาณ จนถึงการออก ''คำรับรองการจัดสรรงบประมาณ'' และการผูกพันงบข้ามปี (50:50) ทำอย่างไร?', 'พ.ร.บ.ส่งเสริม ววน. (ฉ.2) พ.ศ. 2568 แก้ ม.18 (DOC-0026) & ประกาศคำของบ ฉ.3 พ.ศ. 2569 ข้อ 44, 44/1, 44/2, 49 (DOC-0011)', 'D1, D2, D4, D5 (ตรวจแฟ้มคำรับรอง ม.18 และตารางคุมวงเงินผูกพันข้ามปี)', 'ตรวจความถูกต้องของแบบคำรับรอง ม.18 และมติ กสว. อนุมัติจัดสรร', 'เชื่อมโยง CASE-A2-01, CHAIN-01 และคลิปที่ 5');
INSERT INTO interview_questions VALUES ('QO04', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F2 & F5 (P07, P25)', '[Walkthrough การเบิกจ่ายเงินอุดหนุนและระงับจัดสรร] ในกรณีที่หน่วยรับงบประมาณขอเปลี่ยนแปลงรายละเอียดโครงการหรือปฏิบัติไม่เป็นไปตามคำรับรอง ม.18 เจ้าหน้าที่ใช้เกณฑ์ใดในการพิจารณาอนุมัติแก้ไขหรือเสนอระงับการจัดสรรงบประมาณ?', 'ประกาศคำของบ ข้อ 44–49 (DOC-0007, 0011), ระเบียบรับจ่ายเงินกองทุน 2566 (DOC-0006) & คู่มือการเงินสายที่ 3 (DOC-0098)', 'D2, D3, D4, D5 (ตรวจแฟ้มขออนุมัติเปลี่ยนแปลงและหลักฐานการโอนเงินกองทุน)', 'ตรวจความตรงกันของอำนาจอนุมัติ (ผอ.สำนัก F2 <=500,000 บาท ตาม พด.70/2564) และเงื่อนไขคำรับรอง', 'เชื่อมโยง CHAIN-01 & CHAIN-04');
INSERT INTO interview_questions VALUES ('QO05', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน ทุกสำนัก (P05, P23)', '[Walkthrough โครงการวิจัยภายใน ORG] ขอเดินตามแฟ้มโครงการทุน ORG (เช่น สัญญา ORG68F5006): มีการตรวจสอบขอบเขตงานตาม ม.43 วรรคสอง (ไม่แข่งขันกับหน่วยรับงบ) และ ม.9 อย่างไร และใช้แบบฟอร์มตามคู่มือบริหารโครงการ ORG (50 หน้า) ครบถ้วนหรือไม่?', 'พ.ร.บ.สภานโยบายฯ ม.43 วรรคสอง, พ.ร.บ.ส่งเสริม ววน. ม.9 & คู่มือบริหารโครงการ ORG (TSRI-F09-00-002 / DOC-0097)', 'D1, D2, D4, D5 (ตรวจแฟ้มสัญญา ORG, TOR, รายงานการตรวจรับ)', 'ตรวจการอ้างอิงฐานอำนาจ ม.43 วรรคสอง และ ม.9 ในบันทึกขออนุมัติโครงการ ORG', 'เชื่อมโยง CL-04, CASE-A2-01 และคลิปที่ 4');
INSERT INTO interview_questions VALUES ('QO06', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F3 & F5 (P08–P12)', '[Walkthrough การกำกับ PMU และการคืนเงิน 45 วัน] ขอเดินตามแฟ้มกำกับดูแล PMU และการบริหารเงินกองทุน: เจ้าหน้าที่ตรวจสอบการแยกบัญชีเงินอุดหนุนของ PMU การขอขยายเวลาใช้จ่าย (<=1 ปี) และการส่งคืนเงินเหลือจ่ายพร้อมดอกเบี้ยภายใน 45 วันอย่างไร?', 'ประกาศ กสว. การใช้จ่ายเงินอุดหนุนของ PMU ฉ.1–3 (DOC-0016–0018), ระเบียบบริหารกองทุน (DOC-0003) & ประกาศหาผลประโยชน์ (DOC-0015)', 'D2, D3, D4, D5 (ตรวจทะเบียนคุมเงินเหลือจ่ายและใบนำส่งเงินคืนคลัง/กองทุนภายใน 45 วัน)', 'ตรวจวันที่สิ้นสุดสัญญาเทียบกับวันที่ PMU ส่งคืนเงินและดอกเบี้ย (<=45 วัน)', 'เชื่อมโยง CASE-A3-01, CHAIN-04 และคลิปที่ 6, 7');
INSERT INTO interview_questions VALUES ('QO07', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F4 (P13–P18)', '[Walkthrough การใช้ประโยชน์ผลงานวิจัย TRIUP] ขอเดินตามแฟ้มการแจ้งผลงานวิจัยและการขอเป็นเจ้าของผลงานตาม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564: มีการตรวจระยะเวลาแจ้งผลงาน เงื่อนไขข้อยกเว้น ม.8 และการรายงานการใช้ประโยชน์ตามกฎรองทั้ง 14 ฉบับอย่างไร?', 'หมวดที่ 3 พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564 และกฎรอง 14 ฉบับ (TSRI-F03-01-001 ถึง 06-001 / DOC-0037–0051)', 'D1, D2, D4, D5 (ตรวจหนังสือแจ้งผลงานวิจัย คำขอเป็นเจ้าของ และรายงานการใช้ประโยชน์)', 'ตรวจความครบถ้วนของเอกสารตามคู่มือ TRIUP 2 เล่ม (DOC-0050, 0051) และกรอบเวลาตามประกาศ กสว.', 'เชื่อมโยง CASE-A4-01, CHAIN-02 และคลิปที่ 8, 9');
INSERT INTO interview_questions VALUES ('QO08', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F1 & หน่วยภารกิจ IU1 (P10, P19–P20)', '[Walkthrough ระบบฐานข้อมูล NRIIS และชั้นความลับ ม.36] ขอเดินตามกระบวนการรับส่งข้อมูลในระบบ NRIIS: มีการกำหนดสิทธิ์การเข้าถึงข้อมูลที่มีชั้นความลับตาม ม.24–25 เพื่อป้องกันการเปิดเผยข้อมูลโดยมิชอบ (โทษอาญา ม.36) และการตรวจความครบถ้วนของข้อมูลประเมินผลอย่างไร?', 'พ.ร.บ.ส่งเสริม ววน. ม.22–27, 36 (DOC-0025), ระเบียบสภานโยบายฯ ข้อมูล ววน. (DOC-0028), ระเบียบ กสว. ฐานข้อมูล (DOC-0031)', 'D1, D2, D4, D5 (ตรวจ Log การกำหนดสิทธิ์ผู้ใช้งาน NRIIS และบันทึกข้อตกลงรักษาความลับ)', 'ตรวจการแบ่งชั้นความลับและการตั้งค่า Access Control ในระบบฐานข้อมูลกลาง', 'เชื่อมโยง CASE-A5-01, CHAIN-06 และคลิปที่ 10');
INSERT INTO interview_questions VALUES ('QO09', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F5 ด้านโครงสร้าง/บุคคล/จริยธรรม (P21–P24)', '[Walkthrough งานบุคคล โครงสร้างปี 2569 และวินัย] ขอเดินตามแฟ้มงานบุคคลและวินัย: การจัดระดับตำแหน่งตามระเบียบปี 2569 (Level 1–8 / 1A–8A), การทดลองงาน (90–180 วัน), การปฏิบัติงานที่บ้าน (WFH 80:20) และการดำเนินการทางวินัยตามคู่มือวินัย (111 หน้า แบบ วน.1–วน.8) ทำอย่างไร?', 'หมวด 4 โครงสร้างปี 2569 (DOC-0061–64), หมวด 5 บุคคล (DOC-0066–78), หมวด 7 จริยธรรม (DOC-0087–93) & คู่มือวินัย (DOC-0096)', 'D2, D3, D4, D5 (ตรวจคำสั่งบรรจุ/แต่งตั้ง, แบบประเมิน, และสำนวนการสอบสวนวินัย)', 'ตรวจการใช้ข้อบังคับให้ตรงวันเกิดเหตุและการใช้แบบฟอร์มมาตรฐาน วน.1–วน.8', 'เชื่อมโยง CASE-B1-01, CASE-B2-01, CHAIN-03 และคลิปที่ 11, 12');
INSERT INTO interview_questions VALUES ('QO10', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F5 ด้านการเงิน/พัสดุ/สัญญา สกว. & หน่วย IA (P25–P27)', '[Walkthrough การเงิน พัสดุ ปิดบัญชี 90/180 วัน และสัญญา สกว.] ขอเดินตามใบสำคัญจ่ายและแฟ้มพัสดุ: การตรวจแหล่งเงินและอำนาจอนุมัติตาม พด.70–71/2564 (<=500,000 บาท แยก F5 กับ F2), การปิดงบสำนักงานใน 90 วัน vs กองทุน 180 วัน และการติดตามหนี้โครงการรับโอน สกว. (เตือน 30 วัน / บอกเลิก 15 วัน) ทำอย่างไร?', 'หมวด 6 การเงิน (DOC-0079–86), หมวด 8 พัสดุ (DOC-0094–95), คู่มือการเงิน (DOC-0098), ระเบียบชดใช้ทุน สกว. (DOC-0005)', 'D1, D2, D4, D5 (ตรวจใบสั่งซื้อ/จ้าง, ใบสำคัญจ่าย, งบทดลอง 2 บัญชี, แฟ้มติดตามหนี้ สกว.)', 'ตรวจลายมือชื่อผู้อนุมัติเทียบแหล่งเงิน (ม.45 vs ม.55) และวันครบกำหนดส่งงบการเงิน', 'เชื่อมโยง CASE-B3-01, CASE-B4-01, CHAIN-04, CHAIN-05 และคลิปที่ 13, 14, 15');
INSERT INTO learning_clips VALUES (1, 'CLIP-01', 'A1 (การจัดทำแผน ววน.)', 'คณะกรรมการ (กสว. / อนก.)', '80 : 20', 'คลิปยาว 3–5 นาที (Concept + Case)', 'แยกบทบาทผู้เสนอแผนและผู้เห็นชอบ: เส้นแบ่งอำนาจ สภานโยบายฯ – กสว. – สำนักงาน', 'เข้าใจโครงสร้างอำนาจในการจัดทำและให้ความเห็นชอบแผนด้าน ววน. ตาม ม.11(1), ม.41(1) และ ม.44(3) โดยไม่ก้าวล่วงบทบาทระหว่างฝ่ายจัดการและฝ่ายกำกับนโยบาย', '• Hook (0:00–0:45): กรณีศึกษาเมื่อฝ่ายเลขานุการเสนอร่างแผนที่ปรับแก้ตัวชี้วัดโดยยังไม่ผ่านการรับฟังความเห็นตาม ม.13
INSERT INTO learning_clips VALUES (2, 'CLIP-02', 'A1 (การจัดทำแผน ววน.)', 'ผู้บริหารระดับสูง', '60 : 40', 'คลิปยาว 3–5 นาที (Concept + Case)', 'อ่านมติและเงื่อนไขแผนด้าน ววน. 6 องค์ประกอบ: จุดเชื่อมจากยุทธศาสตร์สู่งบประมาณ', 'ตรวจสอบความครบถ้วนขององค์ประกอบแผนด้าน ววน. ทั้ง 6 ด้านตาม พ.ร.บ.ส่งเสริม ววน. ม.12(1)–(6) และการเชื่อมโยงสู่กรอบวงเงินงบประมาณประจำปี', '• Hook (0:00–0:45): ทำไมแผนด้าน ววน. ที่ขาดการกำหนดสัดส่วนงบประมาณตาม ม.12(5) จึงทำให้ขั้นตอนตั้งงบประมาณสะดุด?
INSERT INTO learning_clips VALUES (3, 'CLIP-03', 'A2 (การตั้งและจัดสรรงบประมาณ)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปยาว 3–5 นาที (Walkthrough + Case)', 'กลั่นกรองคำของบประมาณ FF ตามคู่มือ 180 หน้า และประกาศ กสว. (>50 ข้อ)', 'ปฏิบัติตามขั้นตอนและกรอบเวลากลั่นกรองคำของบประมาณ Fundamental Fund (FF) ในระบบ NRIIS ตามคู่มือคำของบ FF และ SOP จัดสรรงบประมาณได้อย่างถูกต้อง', '• Hook (0:00–0:45): สถานการณ์เมื่อหน่วยรับงบประมาณยื่นคำขอ FF ล่าช้าหรือผิดหมวดจาก 8 โปรแกรม 16 แผนงาน
INSERT INTO learning_clips VALUES (4, 'CLIP-04', 'A2 & B1 (ขอบเขตการทำวิจัยเอง ทุน ORG)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'ตรวจคำขอ SF และข้อยกเว้นการทำวิจัยเองของ สกสว. (ทุน ORG) ตามมาตรา 43 วรรคสอง', 'จำแนกขอบเขตโครงการวิจัยที่ สกสว. ทำได้เอง (เฉพาะเพื่อพัฒนานโยบายและงานของ สกสว. ตาม ม.9) ออกจากโครงการที่ห้ามทำแข่งขันกับหน่วยรับงบประมาณตาม ม.43 วรรคสอง', '• 0:00–0:15: กฎเหล็ก ม.43 วรรคสอง ''สกสว. ต้องไม่ทำวิจัยแข่งขันกับหน่วยรับงบประมาณ''
INSERT INTO learning_clips VALUES (5, 'CLIP-05', 'A2 (การจัดสรรปลายน้ำและคำรับรอง ม.18)', 'ผู้บริหารระดับกลาง (ผอ.สำนัก)', '45 : 55', 'คลิปยาว 3–5 นาที (Concept + Case)', 'ไล่วงเงินจาก Pre-ceiling ถึงคำรับรอง ม.18 และงบผูกพันข้ามปี (Multi-year 50:50)', 'กำกับกระบวนการแจ้งยอด Pre-ceiling การปรับคำชี้แจงตามมติ กมธ.งบประมาณ และการออกคำรับรองการจัดสรรงบประมาณตาม ม.18 ที่แก้ไขใหม่ พ.ศ. 2568', '• Hook (0:00–0:45): จุดเปลี่ยนสำคัญเมื่อ พ.ร.บ.ส่งเสริม ววน. (ฉ.2) พ.ศ. 2568 เปลี่ยนจาก ''สัญญารายโครงการ'' เป็น ''คำรับรองการจัดสรรงบประมาณ''
INSERT INTO learning_clips VALUES (6, 'CLIP-06', 'A3 (การพัฒนากองทุนและแยก 2 บัญชี)', 'ผู้บริหารระดับกลาง (ผอ.สำนัก)', '45 : 55', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'จำแนกแหล่งเงินกองทุน (ม.55) ออกจากเงินสำนักงาน (ม.45) และการรับบริจาค', 'คัดแยกรายรับและค่าใช้จ่ายของกองทุน ววน. (ม.54–59) ออกจากเงินของสำนักงาน สกสว. (ม.45) ได้อย่างถูกต้องตามระเบียบบริหารกองทุน', '• 0:00–0:15: เงินบริจาคหรือผลประโยชน์ที่เกิดขึ้น ต้องเข้าบัญชีไหน?
INSERT INTO learning_clips VALUES (7, 'CLIP-07', 'A3 (การหาผลประโยชน์และกำกับ PMU)', 'ผู้บริหารระดับสูง', '60 : 40', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'ตรวจการนำเงินกองทุนไปหาผลประโยชน์และกฎเหล็กคืนเงิน PMU ภายใน 45 วัน', 'กำกับดูแลการนำเงินกองทุนไปหาผลประโยชน์ตามประกาศ กสว. พ.ศ. 2563 และการติดตามให้ PMU ส่งคืนเงินเหลือจ่ายพร้อมดอกเบี้ยภายใน 45 วัน', '• 0:00–0:15: PMU สิ้นสุดปีงบประมาณแล้ว เงินเหลือจ่ายและดอกเบี้ยต้องจัดการอย่างไร?
INSERT INTO learning_clips VALUES (8, 'CLIP-08', 'A4 (การขับเคลื่อนการใช้ประโยชน์ TRIUP)', 'ผู้บริหารระดับกลาง (ผอ.สำนัก)', '45 : 55', 'คลิปยาว 3–5 นาที (Concept + Case)', 'ตรวจสิทธิในผลงานวิจัยตามสัญญาทุนและ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ (TRIUP) พ.ศ. 2564', 'วินิจฉัยสิทธิการเป็นเจ้าของผลงานวิจัยของผู้รับทุนและนักวิจัยตามหลักเกณฑ์ของ TRIUP Act และเงื่อนไขข้อยกเว้นที่ผู้ให้ทุนขอถือสิทธิเองตามมาตรา 8', '• Hook (0:00–0:45): เมื่อมหาวิทยาลัยผู้รับทุนต้องการนำผลงานวิจัยไปจดสิทธิบัตรและอนุญาตให้เอกชนใช้สิทธิ สกสว. ต้องตรวจอะไรบ้าง?
INSERT INTO learning_clips VALUES (9, 'CLIP-09', 'A4 (การแจ้งผลงานและรายงานการใช้ประโยชน์ TRIUP)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'การเปิดเผยผลงานวิจัยและการรายงานการใช้ประโยชน์ภายในระยะเวลาที่กำหนด', 'ตรวจสอบระยะเวลาและแบบฟอร์มในการแจ้งเกิดผลงานวิจัย การยื่นขอเป็นเจ้าของ และการรายงานผลการใช้ประโยชน์ตามประกาศ กสว.', '• 0:00–0:15: นักวิจัยได้ผลงานวิจัยใหม่ ต้องแจ้งภายในกี่วัน และรายงานผลอย่างไร?
INSERT INTO learning_clips VALUES (10, 'CLIP-10', 'A5 (ฐานข้อมูล NRIIS และการประเมินผล ม.77)', 'ผู้บริหารระดับกลาง (ผอ.สำนัก / หัวหน้าหน่วย IU1)', '45 : 55', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'ติดตามตัวชี้วัด ฐานข้อมูลกลาง NRIIS (โทษอาญา ม.36) และผลประเมิน ม.77', 'กำกับการส่งข้อมูลเข้าสู่ระบบฐานข้อมูลกลาง NRIIS การรักษาความลับตามมาตรา 24–25 (โทษอาญา ม.36) และการนำผลประเมิน ม.77 ไปใช้พัฒนาหลักเกณฑ์', '• 0:00–0:15: ข้อมูลโครงการวิจัยที่ยังไม่เปิดเผยใน NRIIS หากรั่วไหลมีโทษอาญาถึงขั้นจำคุก!
INSERT INTO learning_clips VALUES (11, 'CLIP-11', 'B1 (โครงสร้างองค์กรปี 2569 และการมอบอำนาจ)', 'ผู้บริหารระดับสูง', '60 : 40', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'แยกการกำกับส่วนงานตามประกาศปี 2569 ออกจากคำสั่งมอบอำนาจอนุมัติรายธุรกรรม', 'จำแนกขอบเขตการมอบหมายผู้บริหารกำกับดูแลสำนัก (F1–F5) ตามโครงสร้างปี 2569 ออกจากอำนาจอนุมัติจัดซื้อจัดจ้างและสั่งจ่ายเงินรายธุรกรรม', '• 0:00–0:15: การได้รับมอบหมายให้กำกับดูแลสำนัก หมายถึงมีอำนาจอนุมัติพัสดุและสั่งจ่ายเงินทุกวงเงินหรือไม่?
INSERT INTO learning_clips VALUES (12, 'CLIP-12', 'B2 (การบริหารงานบุคคลและวินัย)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'ใช้ข้อบังคับบุคคล โครงสร้างตำแหน่งปี 2569 และคู่มือวินัยตาม ''วันที่เกิดเหตุ''', 'เลือกใช้ข้อบังคับบริหารงานบุคคล ระเบียบกำหนดตำแหน่งและเงินเดือน พ.ศ. 2569 และคู่มือการดำเนินการทางวินัย (111 หน้า) ให้ถูกต้องตามวันที่เกิดข้อเท็จจริง', '• 0:00–0:15: เมื่อเกิดกรณีร้องเรียนหรือพิจารณาสิทธิบุคลากรข้ามปี จะใช้ระเบียบฉบับปีไหน?
INSERT INTO learning_clips VALUES (13, 'CLIP-13', 'B3 (การเงินและพัสดุ 2 สายเงิน)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปยาว 3–5 นาที (Walkthrough + Case)', 'ตรวจแหล่งเงินและวงเงินอนุมัติพัสดุ 500,000 บาท (พด.70/2564) ตามคู่มือการเงิน 3 สาย', 'ตรวจสอบแหล่งเงินและผู้มีอำนาจลงนามอนุมัติจัดซื้อจัดจ้าง/สั่งจ่ายเงินตามคำสั่ง พด.70/2564, พด.71/2564 และคู่มือการเงิน 45 หน้า โดยไม่สับสนระหว่างงบสำนักงานและงบกองทุน', '• Hook (0:00–0:45): กรณีศึกษาเมื่อเจ้าหน้าที่ชงเรื่องจัดจ้างวงเงิน 400,000 บาท โดยใช้เงินกองทุน ววน. แต่เสนอให้ ผอ.สำนัก F5 เป็นผู้อนุมัติ!
INSERT INTO learning_clips VALUES (14, 'CLIP-14', 'B4 (การบัญชีและรายงานการเงินคู่ขนาน)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'แยกบัญชีสำนักงาน (ส่งใน 90 วัน) และบัญชีกองทุน ววน. (ส่งใน 180 วัน)', 'ปฏิบัติตามกรอบเวลาและขั้นตอนการจัดทำงบการเงินและรายงานประจำปีแยก 2 เส้นทางคู่ขนานตามที่ พ.ร.บ.สภานโยบายฯ กำหนด', '• 0:00–0:15: ทำไมการปิดบัญชีของ สกสว. จึงมีทั้งเส้นตาย 90 วัน และ 180 วัน?
INSERT INTO learning_clips VALUES (15, 'CLIP-15', 'B4 (การตรวจสอบภายในและประเมินผลอิสระ)', 'คณะกรรมการ (กสว. / อนก. / คกก.ตรวจสอบ)', '80 : 20', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'สายการรายงานตรงของผู้ตรวจสอบภายใน (IA) และการประเมินผลอิสระตามมาตรา 64', 'กำกับดูแลความเป็นอิสระของหน่วยตรวจสอบภายใน (P27) ตามมาตรา 62–63 และกลไกการประเมินผลการดำเนินงานของ กสว. และ สกสว. โดยคณะกรรมการประเมินอิสระตามมาตรา 64–65', '• 0:00–0:15: หน่วยตรวจสอบภายใน (IA) ขึ้นตรงต่อใครเพื่อหลักประกันความเป็นอิสระ?
INSERT INTO exam_items VALUES ('ITEM-001', 'A1 | คลิปที่ 1 (80:20)', 'คณะกรรมการ / ผู้บริหาร / ปฏิบัติการแผน (F1)', 'ในการประชุมเพื่อพิจารณาร่างแผนด้านวิทยาศาสตร์ วิจัยและนวัตกรรม (ววน.) ของประเทศ ฝ่ายเลขานุการได้เสนอร่างแผนที่ปรับปรุงใหม่โดยขอให้คณะกรรมการอำนวยการ สกสว. (อนก.สกสว.) มีมติให้ความเห็นชอบร่างแผนดังกล่าวเพื่อเสนอคณะรัฐมนตรีต่อไป ข้อใดวินิจฉัยขั้นตอนและฐานอำนาจได้ถูกต้องที่สุด?', 'A. ถูกต้อง เพราะ อนก.สกสว. มีอำนาจกำกับดูแลการดำเนินงานของสำนักงานตามมาตรา 47
INSERT INTO exam_items VALUES ('ITEM-002', 'A1 | คลิปที่ 2 (60:40)', 'ผู้บริหารระดับสูง / สำนัก F1', 'ในการตรวจทานความครบถ้วน (Completeness: C1) ของร่างแผนด้าน ววน. ก่อนเสนอ กสว. ตามมาตรา 44(3) ประกอบ พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 มาตรา 12 และมาตรา 13 ข้อใดคือเงื่อนไขบังคับที่หากขาดไปจะทำให้กระบวนการจัดทำแผนไม่สมบูรณ์ตามกฎหมาย?', 'A. ต้องมีองค์ประกอบครบทั้ง 6 ด้านตามมาตรา 12(1)–(6) และต้องจัดให้มีการรับฟังความคิดเห็นของผู้เกี่ยวข้องตามมาตรา 13
INSERT INTO exam_items VALUES ('ITEM-003', 'A2 | คลิปที่ 3 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F1 & F2', 'ตาม SOP กระบวนการจัดทำกรอบวงเงินและการจัดสรรงบประมาณกองทุน ววน. (TSRI-F11-00-001) และคู่มือคำของบประมาณ FF (TSRI-F09-00-004) เมื่อปิดระบบรับคำของบประมาณ (เปิดรับประมาณ 45 วัน) แล้ว ขั้นตอนการกลั่นกรองคำของบประมาณเบื้องต้นและการเปิดให้หน่วยงานแก้ไขคำขอมีกรอบเวลามาตรฐานอย่างไร?', 'A. กลั่นกรองภายใน 7 วัน และให้หน่วยงานแก้ไขภายใน 7 วัน
INSERT INTO exam_items VALUES ('ITEM-004', 'A2 & B1 | คลิปที่ 4 (30:70)', 'บุคลากรระดับปฏิบัติการ / ทุกสำนัก (ทุน ORG)', 'สำนักหนึ่งของ สกสว. ประสงค์จะตั้งโครงการวิจัยภายใน (ทุน ORG) โดยใช้งบประมาณกองทุน ววน. ในหมวด Strategic Fund (SF) เพื่อพัฒนาชุดเทคโนโลยีต้นแบบแข่งกับมหาวิทยาลัยในระบบ ววน. เจ้าหน้าที่ผู้ตรวจคำขอควรให้ความเห็นตามกฎหมายและคู่มือบริหารโครงการ ORG (TSRI-F09-00-002) อย่างไร?', 'A. อนุมัติได้ทันทีหากวงเงินไม่เกิน 500,000 บาท ตามคำสั่ง พด.70/2564
INSERT INTO exam_items VALUES ('ITEM-005', 'A2 | คลิปที่ 5 (45:55)', 'ผู้บริหารระดับกลาง / สำนัก F2', 'ภายหลังการบังคับใช้ พ.ร.บ.การส่งเสริม ววน. (ฉบับที่ 2) พ.ศ. 2568 ซึ่งแก้ไขเพิ่มเติมมาตรา 18 ประกอบประกาศ กสว. เรื่องหลักเกณฑ์การจัดทำคำของบประมาณ (ฉบับที่ 3) พ.ศ. 2569 ข้อ 44, 44/1 และ 44/2 กลไกการจัดสรรงบประมาณและการผูกพันงบประมาณข้ามปี (Multi-year Promised Grant) เปลี่ยนแปลงไปอย่างไร?', 'A. ยกเลิกการจัดสรรงบประมาณแบบ Block Grant ทั้งหมดและกลับไปทำสัญญารายโครงการทุกบาท
INSERT INTO exam_items VALUES ('ITEM-006', 'A3 | คลิปที่ 6 (45:55)', 'ผู้บริหารระดับกลาง / สำนัก F3 & F5', 'เมื่อมีผู้บริจาคเงินหรือทรัพย์สินให้แก่ สกสว. โดยมีวัตถุประสงค์เพื่อใช้ในการส่งเสริมและสนับสนุนการวิจัยและนวัตกรรมของประเทศ (ไม่ได้บริจาคเพื่อใช้เป็นค่าใช้จ่ายบริหารสำนักงาน) เจ้าหน้าที่ต้องนำเงินดังกล่าวเข้าบัญชีใดและอยู่ภายใต้กรอบระเบียบใด?', 'A. นำเข้าบัญชีเงินสำนักงานตามมาตรา 45 และใช้จ่ายตามข้อบังคับของ อนก.สกสว.
INSERT INTO exam_items VALUES ('ITEM-007', 'A3 | คลิปที่ 7 (60:40)', 'ผู้บริหารระดับสูง / สำนัก F3', 'หน่วยบริหารและจัดการทุน (PMU) แห่งหนึ่งได้รับจัดสรรเงินอุดหนุนจากกองทุน ววน. เมื่อสิ้นสุดระยะเวลาการใช้จ่ายเงินอุดหนุนตามที่กำหนดแล้ว ปรากฏว่ายังมีเงินอุดหนุนเหลือจ่ายและมีดอกผลที่เกิดจากเงินฝากธนาคารของโครงการ ตามประกาศ กสว. เรื่องแนวทางการใช้จ่ายเงินอุดหนุนของ PMU (TSRI-F01-04-010 ถึง 012) PMU ต้องดำเนินการอย่างไร?', 'A. PMU สามารถนำเงินเหลือจ่ายและดอกเบี้ยไปสมทบเป็นงบบริหารสำนักงานของ PMU ในปีถัดไปได้ทันที
INSERT INTO exam_items VALUES ('ITEM-008', 'A4 | คลิปที่ 8 (45:55)', 'ผู้บริหารระดับกลาง / สำนัก F4', 'ตาม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 (TRIUP Act: TSRI-F03-01-001) และประกาศ กสว. ที่เกี่ยวข้อง เมื่อหน่วยรับงบประมาณสร้างผลงานวิจัยจากทุนของกองทุน ววน. สำเร็จ หลักการพื้นฐานเกี่ยวกับความเป็นเจ้าของผลงานวิจัยคือข้อใด?', 'A. ผลงานวิจัยตกเป็นของ สกสว. ในฐานะผู้ให้ทุนทุกกรณีโดยไม่มีข้อยกเว้น
INSERT INTO exam_items VALUES ('ITEM-009', 'A4 | คลิปที่ 9 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F4', 'เมื่อผู้รับทุนได้รับอนุมัติให้เป็นเจ้าของผลงานวิจัยตาม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564 แล้ว หน้าที่ตามกฎหมายที่ผู้รับทุนต้องปฏิบัติอย่างต่อเนื่องต่อผู้ให้ทุน และเจ้าหน้าที่สำนัก F4 ต้องตรวจติดตามตามประกาศ กสว. ในหมวดที่ 3 คือข้อใด?', 'A. ไม่ต้องดำเนินการใดๆ อีกเนื่องจากความเป็นเจ้าของโอนขาดไปแล้ว
INSERT INTO exam_items VALUES ('ITEM-010', 'A5 | คลิปที่ 10 (45:55)', 'ผู้บริหารระดับกลาง / สำนัก F1 & หน่วยภารกิจ IU1', 'เจ้าหน้าที่ผู้ดูแลระบบฐานข้อมูลกลางด้าน ววน. (NRIIS) ล่วงรู้ข้อมูลอันเป็นความลับของโครงการวิจัยที่ยังไม่เปิดเผยต่อสาธารณะเนื่องจากการปฏิบัติหน้าที่ แล้วนำข้อมูลดังกล่าวไปเปิดเผยแก่บุคคลภายนอกโดยมิชอบด้วยกฎหมาย ตาม พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 มาตรา 24–25 และมาตรา 36 มีผลทางกฎหมายอย่างไร?', 'A. มีโทษทางวินัยตักเตือนเป็นหนังสือเท่านั้น ไม่มีโทษทางอาญา
INSERT INTO exam_items VALUES ('ITEM-011', 'B1 | คลิปที่ 11 (60:40)', 'ผู้บริหารระดับสูง / สำนัก F5', 'ตามประกาศคณะกรรมการอำนวยการ สกสว. เรื่องการแบ่งส่วนงานและขอบเขตหน้าที่ของส่วนงาน พ.ศ. 2569 (TSRI-F04-00-012 / DOC-0063) โครงสร้างส่วนงานของ สกสว. แบ่งออกเป็นกี่สำนัก กี่หน่วยภารกิจ และหน่วยตรวจสอบภายในมีสายการรายงานอย่างไร?', 'A. แบ่งเป็น 3 สำนัก 2 หน่วยภารกิจ โดยหน่วยตรวจสอบภายในสังกัดฝ่ายการเงิน
INSERT INTO exam_items VALUES ('ITEM-012', 'B2 | คลิปที่ 12 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F5 (งานบุคคลและวินัย)', 'ตามข้อบังคับ อนก.สกสว. ว่าด้วยการบริหารงานบุคคลและวินัย (หมวดที่ 5) ประกอบคู่มือการดำเนินการทางวินัย พ.ศ. 2568 (TSRI-F09-00-001 จำนวน 111 หน้า) ข้อใดระบุกรอบเวลาการดำเนินการทางวินัยและสิทธิการอุทธรณ์ได้ถูกต้อง?', 'A. สืบสวนข้อเท็จจริงภายใน 30 วัน (ขยายได้ไม่เกิน 15 วัน), สอบสวนวินัยภายใน 60 วัน (ขยายได้ 2 ครั้ง ครั้งละไม่เกิน 30 วัน) และผู้ถูกลงโทษมีสิทธิยื่นอุทธรณ์ต่อ อนก.สกสว. ภายใน 30 วันนับแต่วันทราบคำสั่ง
INSERT INTO exam_items VALUES ('ITEM-013', 'B3 | คลิปที่ 13 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F5 & F2 (การเงินและพัสดุ)', 'ในการจัดซื้อจัดจ้างและการสั่งจ่ายเงินวงเงิน 450,000 บาท หากรายการแรกเป็น ''การจัดซื้อครุภัณฑ์สำนักงานโดยใช้งบประมาณของสำนักงาน (มาตรา 45)'' และรายการที่สองเป็น ''การเบิกจ่ายเงินอุดหนุนภายใต้ภารกิจกองทุน ววน. (มาตรา 55)'' ตามคำสั่ง สกสว. ที่ พด. 70/2564 (TSRI-F08-00-001) และคู่มือการเงิน (TSRI-F09-00-003) ใครคือผู้รับมอบอำนาจอนุมัติในแต่ละรายการ?', 'A. ผู้อำนวยการสำนักบริหารและพัฒนาองค์กร (F5) มีอำนาจอนุมัติได้ทั้งสองรายการเพราะดูแลงานพัสดุทั้งหมด
INSERT INTO exam_items VALUES ('ITEM-014', 'B4 | คลิปที่ 14 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F5 (ฝ่ายบัญชี)', 'ในการปิดบัญชีและจัดส่งรายงานการเงินประจำปีของ สกสว. ตาม พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ข้อใดระบุเส้นตายและผู้รับรายงานการเงินของ ''งบสำนักงาน สกสว.'' เปรียบเทียบกับ ''งบกองทุน ววน.'' ได้ถูกต้องตามกฎหมาย?', 'A. ส่งทั้งสองงบให้กรมบัญชีกลางภายใน 60 วันนับแต่วันสิ้นปีงบประมาณ
INSERT INTO exam_items VALUES ('ITEM-015', 'B4 | คลิปที่ 15 (80:20)', 'คณะกรรมการ / ผู้บริหาร / หน่วยตรวจสอบภายใน (IA)', 'ตาม พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 มาตรา 62–65 กลไกการตรวจสอบและประเมินผลการดำเนินงานของกองทุน ววน. และ สกสว. กำหนดให้มีองค์กรใดทำหน้าที่ตรวจสอบภายในและองค์กรใดทำหน้าที่ประเมินผลการดำเนินงานอย่างเป็นอิสระ?', 'A. ให้ผู้บริหารสำนัก F5 เป็นผู้ประเมินตนเองทั้งหมดโดยไม่ต้องมีคณะกรรมการภายนอก
